// 家族共有の2クエリ（visibility="household" / ownerUid=自分）の結果を id でマージする純粋関数。
// 入力は {id, data} の配列（data は Firestore の生データ）。重複は後勝ちで1件に畳む。
const mergeFsDocs = (listA, listB) => { const byId = new Map(); [...(listA || []), ...(listB || [])].forEach(d => { if (d && d.id) byId.set(d.id, d); }); return [...byId.values()]; };
const iso = (d) => { const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),da=String(d.getDate()).padStart(2,"0"); return `${y}-${m}-${da}`; };
const plusDays = (n) => { const d=new Date(); d.setDate(d.getDate()+n); return iso(d); };
const daysUntil = (s) => { if(!s||typeof s!=="string")return null; const[y,m,d]=s.split("-").map(Number); const due=new Date(y,m-1,d),now=new Date(),t0=new Date(now.getFullYear(),now.getMonth(),now.getDate()); return Math.round((due-t0)/86400000); };
const addInterval = (s,rep,days) => { const[y,m,d]=s.split("-").map(Number); const dt=new Date(y,m-1,d); if(rep==="daily")dt.setDate(dt.getDate()+1); else if(rep==="weekly"){if(Array.isArray(days)&&days.length){return nextWeeklyDate(s,days);}dt.setDate(dt.getDate()+7);} else if(rep==="monthly")dt.setMonth(dt.getMonth()+1); else if(rep==="yearly")dt.setFullYear(dt.getFullYear()+1); return iso(dt); };
// 繰り返し（曜日指定の毎週）: repeatDays は曜日番号 0=日〜6=土の配列。開始日より後の最初の該当日を返す。
const REPEAT_WEEKDAYS=[1,2,3,4,5]; // 平日（月〜金）
const REPEAT_WEEKEND=[0,6]; // 週末（土・日）
const BYDAY2=["SU","MO","TU","WE","TH","FR","SA"];
const repeatDaysOf=(x)=>{if(!x||x.repeat!=="weekly")return null;if(!Array.isArray(x.repeatDays))return null;const d=x.repeatDays.filter(n=>typeof n==="number"&&n>=0&&n<=6);return d.length?d:null;};
// ルーティンがその日に実施対象か（追加項目・2026-11-26）。repeat:"daily"/未設定は毎日。
// weekly は repeatDays を優先し、無い旧データは作成日の曜日をアンカーにする（後方互換）。
const routineDueOn=(r,dateIso)=>{if(!r||!r.repeat||r.repeat==="daily")return true;if(r.repeat==="weekly"){const days=repeatDaysOf(r);const dow=dowOf(dateIso);if(days)return days.indexOf(dow)>=0;if(r.createdAt)return dowOf(iso(new Date(r.createdAt)))===dow;return true;}return true;};
// 赤ちゃんの成長曲線の「目安」帯（月齢→体重kgの下限/上限）。公的な発育目安をもとにした
// 概ねの範囲で、医療助言ではない。男女の平均寄りの値を補間して使う。
const BABY_WEIGHT_BAND=[[0,2.5,4.4],[1,3.4,5.8],[2,4.3,7.1],[3,5.0,8.0],[4,5.6,8.7],[5,6.1,9.3],[6,6.5,9.8],[7,6.8,10.3],[8,7.1,10.7],[9,7.4,11.1],[10,7.6,11.5],[11,7.8,11.8],[12,8.0,12.1],[15,8.5,13.0],[18,9.0,13.9],[21,9.5,14.7],[24,10.0,15.5]];
const ageMonthsAt=(birthday,dateIso)=>{if(!birthday||!dateIso)return null;const b=new Date(birthday+"T00:00:00"),d=new Date(dateIso+"T00:00:00");if(isNaN(b.getTime())||isNaN(d.getTime()))return null;let m=(d.getFullYear()-b.getFullYear())*12+(d.getMonth()-b.getMonth());if(d.getDate()<b.getDate())m-=1;return m<0?null:m;};
const babyWeightBandAt=(birthday,dateIso)=>{const m=ageMonthsAt(birthday,dateIso);if(m==null||m>24)return null;const T=BABY_WEIGHT_BAND;if(m<=T[0][0])return{lo:T[0][1],hi:T[0][2]};for(let i=1;i<T.length;i++){if(m<=T[i][0]){const a=T[i-1],b=T[i];const f=(m-a[0])/(b[0]-a[0]);return{lo:a[1]+(b[1]-a[1])*f,hi:a[2]+(b[2]-a[2])*f};}}const last=T[T.length-1];return{lo:last[1],hi:last[2]};};
const nextWeeklyDate=(fromIso,days)=>{const[y,m,d]=fromIso.split("-").map(Number);const dt=new Date(y,m-1,d);for(let i=0;i<7;i++){dt.setDate(dt.getDate()+1);if(days.indexOf(dt.getDay())>=0)return iso(dt);}return iso(dt);};
const rruleFor=(item)=>{if(!item||!item.repeat||item.repeat==="none")return null;const rmap={daily:"DAILY",weekly:"WEEKLY",monthly:"MONTHLY",yearly:"YEARLY"};let r=`RRULE:FREQ=${rmap[item.repeat]||"WEEKLY"}`;if(item.repeat==="weekly"){const days=repeatDaysOf(item);if(days)r+=`;BYDAY=${days.map(d=>BYDAY2[d]).join(",")}`;}return r;};
// ISO日付に n ヶ月を足す（防災備蓄の「交換・賞味の目安」初期値の計算用）。不正な日付なら ""。
const addMonthsIso = (s,months) => { if(!s||typeof s!=="string")return ""; const[y,m,d]=s.split("-").map(Number); if(!y||!m||!d)return ""; const dt=new Date(y,m-1+months,d); return iso(dt); };
// ISO日付から今日までの経過（年・月・日）。未来日なら null。
const elapsedParts = (s) => { if(!s||typeof s!=="string")return null; const[y,m,d]=s.split("-").map(Number); if(!y||!m||!d)return null; const now=new Date(); const t0=new Date(now.getFullYear(),now.getMonth(),now.getDate()); const from=new Date(y,m-1,d); if(from>t0)return null; let months=(t0.getFullYear()-from.getFullYear())*12+(t0.getMonth()-from.getMonth()); if(t0.getDate()<from.getDate())months--; const days=Math.round((t0-from)/86400000); return {years:Math.floor(months/12),months:months%12,totalMonths:months,days}; };
// ビュー／オーバーレイを開いたら先頭から表示する（スクロール位置を引き継がない共通処理）。
const scrollViewTop = () => { try{window.scrollTo(0,0);}catch(e){} try{document.querySelectorAll(".yl-help-ov").forEach(el=>{el.scrollTop=0;});}catch(e){} };
const fmtDate = (s) => { if(!s||typeof s!=="string")return""; const[,m,d]=s.split("-").map(Number); return`${m}/${d}`; };
// 授乳タイマー用のフォーマッタ（ms タイムスタンプ基準）。
const isoOf = (ms) => iso(new Date(ms));
const fmtDur = (sec) => {const S=(n)=>APP_LANG==="ja"||APP_LANG==="zh"?`${n}秒`:`${n}s`;const M=(n)=>APP_LANG==="ja"||APP_LANG==="zh"?`${n}分`:`${n}m`;return sec<60?S(sec):`${M(Math.floor(sec/60))}${sec%60?S(sec%60):""}`;};
const fmtClock = (ms) => { const d=new Date(ms); return `${String(d.getHours()).padStart(2,"0")}:${String(d.getMinutes()).padStart(2,"0")}`; };
const sinceLabel = (ms) => { const mins=Math.max(0,Math.floor((Date.now()-ms)/60000)); const M=(n)=>APP_LANG==="ja"||APP_LANG==="zh"?`${n}分`:`${n}m`; const H=(n)=>APP_LANG==="ja"||APP_LANG==="zh"?`${n}時間`:`${n}h`; if(mins<1)return tr(APP_LANG,"time.justNow"); if(mins<60)return M(mins); const h=Math.floor(mins/60),m=mins%60; return`${H(h)}${m?M(m):""}`; };
// 散歩記録：2点間の距離（メートル・Haversine）、距離表記、GPSルートのSVGトレース。
const haversineM = (a,b) => { const R=6371000,rad=Math.PI/180; const dLat=(b.lat-a.lat)*rad,dLng=(b.lng-a.lng)*rad; const s=Math.sin(dLat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dLng/2)**2; return 2*R*Math.asin(Math.min(1,Math.sqrt(s))); };
const fmtDist = (m) => m==null?"—":m>=1000?`${(m/1000).toFixed(2)}km`:`${Math.round(m)}m`;
// 共有画像に入れるアプリのURL（実行時のホスト。取れなければ公開URLにフォールバック）。
const BRAND_HOST=(()=>{try{const h=(typeof location!=="undefined"&&location.host)||"";
  // ネイティブ（Capacitor）ではホストが localhost 等になるため、ポスター等の表示は正規ドメインに固定。
  if(!h||/^localhost|^127\.|^10\.|^192\.168\.|capacitor/i.test(h)||(typeof window!=="undefined"&&window.Capacitor))return"loalife-poster.vercel.app";
  return h;}catch(e){return"loalife-poster.vercel.app";}})();
// 散歩ルートを一時停止の区切り（{brk:true}）でセグメントに分ける。座標を持たない要素は無視する。
const routeSegments = (route) => { if(!Array.isArray(route))return[]; const segs=[]; let cur=[]; route.forEach(p=>{ if(!p)return; if(p.brk){ if(cur.length)segs.push(cur); cur=[]; return; } if(typeof p.lat!=="number"||typeof p.lng!=="number")return; cur.push(p); }); if(cur.length)segs.push(cur); return segs; };
// ルートをSVG座標へ投影する。経度に cos(緯度) 補正を入れ、等倍フィット（引き伸ばして歪ませない）で配置する。
const routeXY = (route,w,h,pad=6) => { const segs=routeSegments(route); const all=segs.flat(); if(!all.length)return{segs:[],first:null,last:null}; const midLa=all.reduce((s,p)=>s+p.lat,0)/all.length*Math.PI/180; const kx=Math.cos(midLa)||1; let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity; all.forEach(p=>{const x=p.lng*kx,y=p.lat; if(x<minX)minX=x; if(x>maxX)maxX=x; if(y<minY)minY=y; if(y>maxY)maxY=y;}); const spanX=Math.max(1e-9,maxX-minX),spanY=Math.max(1e-9,maxY-minY); const iw=w-2*pad,ih=h-2*pad; const sc=Math.min(iw/spanX,ih/spanY); const ox=pad+(iw-spanX*sc)/2,oy=pad+(ih-spanY*sc)/2; const proj=(p)=>({x:+(ox+(p.lng*kx-minX)*sc).toFixed(1),y:+(oy+(maxY-p.lat)*sc).toFixed(1)}); return{segs:segs.map(s=>s.map(proj)),first:proj(all[0]),last:proj(all[all.length-1])}; };
const routePath = (route,w,h,pad=6) => { const{segs}=routeXY(route,w,h,pad); const s=segs.find(g=>g.length>=2); return s?s.map(p=>`${p.x},${p.y}`).join(" "):""; };
// 散歩の月間めやす（犬種サイズ×年齢）。獣医の助言ではなく、あくまでゆるやかな目安。
const WALK_BREED_SMALL=["チワワ","トイプードル","ダックス","ポメラニアン","シーズー","マルチーズ","ヨークシャー","パピヨン","豆柴","カニンヘン","チン","キャバリア","ペキニーズ","ピンシャー","ビション","パグ","フレンチブル","ボストン"];
const WALK_BREED_LARGE=["ゴールデン","ラブラドール","レトリバー","シェパード","ハスキー","ボーダーコリー","バーニーズ","ピレニーズ","ドーベルマン","ダルメシアン","秋田","ワイマラナー","ロットワイラー","スタンダードプードル","フラットコーテッド","コリー","ボクサー","グレート"];
const walkSizeOf=(breed)=>{const b=(breed||"");if(WALK_BREED_LARGE.some(k=>b.includes(k)))return"large";if(WALK_BREED_SMALL.some(k=>b.includes(k)))return"small";return"medium";};
const walkGoalFor=(m)=>{
  if(!m||m.species!=="dog")return null;
  const size=walkSizeOf(m.breed);
  const mo=typeof monthsOld==="function"?monthsOld(m.birthday):null;
  const stage=mo==null?"adult":mo<12?"puppy":mo>=96?"senior":"adult"; // <1歳=子犬, 8歳以上=シニア
  const baseKm={small:2,medium:3.5,large:5.5}[size];
  const factor={puppy:0.5,adult:1,senior:0.65}[stage];
  const monthlyKm=Math.round(baseKm*factor*30);
  const dailyWalks=size==="small"?1:2;
  const monthlyWalks=Math.round(dailyWalks*(stage==="senior"?0.7:1)*30);
  return{size,stage,monthlyKm,monthlyWalks,sizeLabel:{small:"小型",medium:"中型",large:"大型"}[size],stageLabel:{puppy:"子犬",adult:"成犬",senior:"シニア"}[stage],knownBreed:size!=="medium"||!!(m.breed&&m.breed.trim()),knownAge:mo!=null};
};
const daysBetween = (a,b) => { const[ay,am,ad]=a.split("-").map(Number),[by,bm,bd]=b.split("-").map(Number); return Math.round((new Date(by,bm-1,bd)-new Date(ay,am-1,ad))/86400000); };
const addDays = (s,n) => { const[y,m,d]=s.split("-").map(Number); const dt=new Date(y,m-1,d); dt.setDate(dt.getDate()+n); return iso(dt); };
const fmtBirthday = (s) => { if(!s||typeof s!=="string")return""; const[,mo,d]=s.split("-").map(Number); if(!mo||!d)return""; if(APP_LANG==="ja")return`${mo}月${d}日`; try{return new Intl.DateTimeFormat((typeof LOCALES!=="undefined"&&LOCALES[APP_LANG])||"en-US",{month:"short",day:"numeric"}).format(new Date(2001,mo-1,d));}catch(e){return`${mo}/${d}`;} };

// dream は選択カテゴリから廃止。既存データ（過去に作成された「夢」項目）の表示互換のため定義のみ残す。
// ===== 演出系ヘルパー（カウントアップ／紙吹雪） =====
const CountUp=({value,dur=1300,decimals=0,className})=>{
  const[disp,setDisp]=useState(0);
  const ref=useRef(null);
  useEffect(()=>{
    const target=Number(value)||0;const t0=performance.now();let raf=0;
    const tick=(now)=>{const p=Math.min(1,(now-t0)/dur);const e=1-Math.pow(1-p,3);setDisp(target*e);if(p<1)raf=requestAnimationFrame(tick);};
    raf=requestAnimationFrame(tick);return()=>cancelAnimationFrame(raf);
  },[value,dur]);
  const txt=decimals>0?disp.toFixed(decimals):String(Math.round(disp));
  return <span ref={ref} className={className}>{txt}</span>;
};
const CONFETTI_COLORS=["#FF9FBF","#FFB26B","#7FC8A9","#6FA8DC","#D9A441","#B39DDB"];
const Confetti=({fire})=>{
  const[pieces,setPieces]=useState([]);
  useEffect(()=>{
    if(!fire)return;
    const ps=Array.from({length:28},(_,i)=>({id:i,left:4+Math.random()*92,delay:Math.random()*0.35,dur:2.2+Math.random()*1.6,color:CONFETTI_COLORS[i%CONFETTI_COLORS.length],size:6+Math.random()*7,round:Math.random()>0.5,rot:Math.random()*360}));
    setPieces(ps);const tm=setTimeout(()=>setPieces([]),4600);return()=>clearTimeout(tm);
  },[fire]);
  if(!pieces.length)return null;
  return <div className="yl-confetti" aria-hidden="true">{pieces.map(p=><span key={p.id} className="yl-confetti-piece" style={{left:p.left+"%",width:p.size,height:p.size*(p.round?1:0.45),background:p.color,borderRadius:p.round?"50%":"2px",animationDelay:p.delay+"s",animationDuration:p.dur+"s",transform:`rotate(${p.rot}deg)`}}/>)}</div>;
};
// ===== 今日の一句：その日の記録から川柳（他言語は一言日記）を自動生成 =====
const seededRand=(seed)=>{let s=seed%2147483647;if(s<=0)s+=2147483646;return()=>{s=s*16807%2147483647;return(s-1)/2147483646;};};
const dayFacts=(items,dateIso)=>{
  const f={walks:0,walkMin:0,walkKm:0,feeds:0,toilet:0,toiletOk:0,diary:0,health:0,memories:0,spaces:new Set()};
  (items||[]).forEach(x=>{
    const d=x.type==="walk"?(x.date||""):(x.date||"");
    if(d!==dateIso)return;
    if(x.type==="walk"){f.walks++;f.walkMin+=Math.round((x.durationSec||0)/60);f.walkKm+=(x.distanceM||0)/1000;if(x.space)f.spaces.add(x.space);}
    else if(x.type==="feed"){f.feeds++;if(x.space)f.spaces.add(x.space);}
    else if(x.type==="toilet"){f.toilet++;if(x.ok||x.success)f.toiletOk++;if(x.space)f.spaces.add(x.space);}
    else if(x.type==="diary"){f.diary++;if(x.space)f.spaces.add(x.space);}
    else if(x.type==="health"){f.health++;if(x.space)f.spaces.add(x.space);}
    else if(x.type==="memory"){f.memories++;if(x.space)f.spaces.add(x.space);}
  });
  f.walkKm=Math.round(f.walkKm*10)/10;
  f.any=f.walks+f.feeds+f.toilet+f.diary+f.health+f.memories>0;
  return f;
};
