// 認証アクション（メール内リンク）のLOALIFE内蔵ハンドラ。
// Firebaseの汎用ページではなく、アプリ自身のデザインと言語で処理する公開ビュー。
// verifyEmail=確認完了 / resetPassword=新しいパスワード設定 / recoverEmail=変更の取り消し /
// verifyAndChangeEmail=新しいアドレスの確認。どの結果でも必ず出口（サインイン／アプリを開く）を出す。
const AuthActionView=({action,lang,signedIn,onLang,onSignIn,onOpenApp,onResend})=>{
  const mode=action.mode,oobCode=action.oobCode;
  const[phase,setPhase]=useState("working"); // working | ok | form | done | invalid
  const[email,setEmail]=useState("");
  const[pw,setPw]=useState("");
  const[busy,setBusy]=useState(false);
  const[err,setErr]=useState("");
  useEffect(()=>{
    let alive=true;
    (async()=>{
      if(!fbAuth){if(alive)setPhase("invalid");return;}
      try{
        if(mode==="resetPassword"){
          const em=await verifyPasswordResetCode(fbAuth,oobCode);
          if(!alive)return;
          setEmail(em||"");setPhase("form");
        }else{
          await applyActionCode(fbAuth,oobCode);
          if(!alive)return;
          setPhase("ok");
        }
      }catch(e){if(alive)setPhase("invalid");}
    })();
    return()=>{alive=false;};
  },[]);
  const submitReset=async()=>{
    if(pw.length<6){setErr(tr(lang,"auth.errWeakPw"));return;}
    setBusy(true);setErr("");
    try{
      await confirmPasswordReset(fbAuth,oobCode,pw);
      setPhase("done");
    }catch(e){
      const c=(e&&e.code)||"";
      if(c.indexOf("weak-password")>=0)setErr(tr(lang,"auth.errWeakPw"));
      else if(c.indexOf("expired-action-code")>=0||c.indexOf("invalid-action-code")>=0)setPhase("invalid");
      else setErr(tr(lang,"auth.errGenericFail"));
    }
    setBusy(false);
  };
  const okTitle=mode==="recoverEmail"?tr(lang,"auth.actRecoveredTitle"):mode==="verifyAndChangeEmail"?tr(lang,"auth.actChangedTitle"):tr(lang,"auth.actVerifiedTitle");
  const okBody=mode==="recoverEmail"?tr(lang,"auth.actRecoveredBody"):mode==="verifyAndChangeEmail"?tr(lang,"auth.actChangedBody"):tr(lang,"auth.actVerifiedBody");
  const signInBtn=signedIn
    ?<button className="yl-petpage-cta" onClick={onOpenApp}>{tr(lang,"auth.actOpenApp")}</button>
    :<button className="yl-petpage-cta" onClick={onSignIn}>{tr(lang,"auth.actSignIn")}</button>;
  return(
    <div className="yl-petpage">
      <div className="yl-petpage-card">
        <div className="yl-petpage-ava">✉️</div>
        {phase==="working"&&<p className="yl-petpage-born">{tr(lang,"auth.actWorking")}</p>}
        {phase==="ok"&&<><h2 className="yl-petpage-name" style={{fontSize:24}}>{okTitle}</h2><p className="yl-petpage-born">{okBody}</p>{signInBtn}</>}
        {phase==="form"&&<><h2 className="yl-petpage-name" style={{fontSize:24}}>{tr(lang,"auth.actResetTitle")}</h2>{email&&<p className="yl-petpage-born">{email}</p>}<input className="yl-petpage-input" type="password" autoComplete="new-password" value={pw} onChange={e=>setPw(e.target.value)} placeholder={tr(lang,"auth.actNewPwPh")}/>{err&&<p className="yl-petpage-err">{err}</p>}<button className="yl-petpage-cta" onClick={submitReset} disabled={busy}>{busy?tr(lang,"auth.processing"):tr(lang,"auth.actResetDo")}</button></>}
        {phase==="done"&&<><h2 className="yl-petpage-name" style={{fontSize:24}}>{tr(lang,"auth.actResetDoneTitle")}</h2><p className="yl-petpage-born">{tr(lang,"auth.actResetDoneBody")}</p>{signInBtn}</>}
        {phase==="invalid"&&<><h2 className="yl-petpage-name" style={{fontSize:24}}>{tr(lang,"auth.actInvalidTitle")}</h2><p className="yl-petpage-born">{tr(lang,"auth.actInvalidBody")}</p>{mode==="resetPassword"
          ?<><button className="yl-petpage-cta" onClick={onResend}>{tr(lang,"auth.actResend")}</button><button className="yl-petpage-cta sub" onClick={onOpenApp}>{tr(lang,"auth.actOpenApp")}</button></>
          :<>{signInBtn}<button className="yl-petpage-cta sub" onClick={onOpenApp}>{tr(lang,"auth.actOpenApp")}</button></>}</>}
        <p className="yl-petpage-brand">🐾 {tr(lang,"brand.footer")}</p>
        <PublicLangSwitch lang={lang} onLang={onLang}/>
      </div>
    </div>
  );
};
const StoryPlayer=({pages,year,onBack,lang})=>{
  const[idx,setIdx]=useState(0);
  const[done,setDone]=useState(false);
  const[rec,setRec]=useState(false);
  const[note,setNote]=useState("");
  const canRec=typeof MediaRecorder!=="undefined";
  const last=pages.length-1;
  useEffect(()=>{
    if(rec)return;
    if(idx>=last){setDone(true);return;}
    const tm=setTimeout(()=>setIdx(i=>Math.min(last,i+1)),4600);
    return()=>clearTimeout(tm);
  },[idx,last]);
  const saveStoryVideo=async()=>{
    if(!canRec||rec)return;
    setRec(true);setNote(tr(lang,"video.recording"));
    try{
      const W=720,H=1280;const cv=document.createElement("canvas");cv.width=W;cv.height=H;
      const ctx=cv.getContext("2d");
      const imgs=await Promise.all(pages.map(async(pg)=>{
        if(!pg.photo)return null;
        return await new Promise(res=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>res(null);im.src=pg.photo;});
      }));
      const stream=cv.captureStream(30);
      const mime=["video/mp4;codecs=avc1","video/mp4","video/webm;codecs=vp9","video/webm"].find(m=>{try{return MediaRecorder.isTypeSupported(m);}catch(e){return false;}})||"";
      const mr=new MediaRecorder(stream,mime?{mimeType:mime,videoBitsPerSecond:6000000}:{videoBitsPerSecond:6000000});
      const chunks=[];mr.ondataavailable=e=>{if(e.data&&e.data.size)chunks.push(e.data);};
      const stopped=new Promise(r=>{mr.onstop=r;});
      const wrapTxt=(s,max)=>{const out=[];let line="";for(const ch of String(s||"")){line+=ch;if(line.length>=max){out.push(line);line="";}}if(line)out.push(line);return out;};
      const draw=(pg,im,ci)=>{
        const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,"#3A2A1A");g.addColorStop(0.55,"#6B4226");g.addColorStop(1,"#A05C2C");ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
        if(pg.photo&&im){
          const base=Math.max(W/im.width,H/im.height);const dw=im.width*base,dh=im.height*base;
          ctx.drawImage(im,(W-dw)/2,(H-dh)/2,dw,dh);
          const g2=ctx.createLinearGradient(0,H-360,0,H);g2.addColorStop(0,"rgba(10,6,3,0)");g2.addColorStop(1,"rgba(10,6,3,0.66)");ctx.fillStyle=g2;ctx.fillRect(0,H-360,W,360);
        }
        const bw=(W-72)/pages.length;
        pages.forEach((_,i)=>{ctx.fillStyle=i<ci?"#FFE9A8":"rgba(255,255,255,0.30)";ctx.fillRect(36+i*bw,26,bw-8,7);});
        ctx.textAlign="center";
        if(pg.photo){
          if(pg.label){ctx.fillStyle="#FFF";ctx.font="800 44px sans-serif";ctx.fillText(pg.label,W/2,H-90);}
        }else{
          ctx.font="150px sans-serif";ctx.fillText(pg.emoji||"✨",W/2,430);
          if(pg.kicker){ctx.fillStyle="#F3D9B0";ctx.font="700 30px sans-serif";ctx.fillText(pg.kicker,W/2,540);}
          let y=540;
          if(pg.num!=null){ctx.fillStyle="#FFF7E8";ctx.font="900 190px sans-serif";const nv=(pg.decimals?Number(pg.num).toFixed(pg.decimals):String(Math.round(pg.num)))+(pg.suffix||"");ctx.fillText(nv,W/2,760);y=760;}
          if(pg.head){ctx.fillStyle="#FFF7E8";ctx.font="900 56px sans-serif";const ls=wrapTxt(pg.head,11);ls.forEach((l,i)=>ctx.fillText(l,W/2,y+110+i*72));y=y+110+(ls.length-1)*72;}
          if(pg.label){ctx.fillStyle="#FFE9A8";ctx.font="800 42px sans-serif";ctx.fillText(pg.label,W/2,y+96);y+=96;}
          if(pg.lines&&pg.lines.length){ctx.fillStyle="#FFF1DC";ctx.font="600 36px sans-serif";let ly=y+110;pg.lines.forEach(l=>{wrapTxt(l,15).forEach(wl=>{ctx.fillText(wl,W/2,ly);ly+=52;});});}
        }
        ctx.fillStyle="rgba(255,247,232,0.8)";ctx.font="600 27px sans-serif";ctx.fillText("🐾 "+tr(lang,"brand.footer")+" · LOALIFE "+year,W/2,H-36);
        ctx.textAlign="left";
      };
      mr.start(200);
      const per=2400;const total=per*pages.length;const t0=performance.now();
      await new Promise(res=>{
        const frame=(now)=>{
          const el=now-t0;
          if(el>=total){res();return;}
          const ci=Math.min(pages.length-1,Math.floor(el/per));
          setIdx(ci);
          draw(pages[ci],imgs[ci],ci);
          requestAnimationFrame(frame);
        };
        requestAnimationFrame(frame);
      });
      mr.stop();await stopped;
      const blob=new Blob(chunks,{type:mr.mimeType||"video/webm"});
      const ext=(mr.mimeType||"").includes("mp4")?"mp4":"webm";
      const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`loalife-wrapped-${Date.now()}.${ext}`;document.body.appendChild(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(a.href),4000);
      setNote(tr(lang,"video.saved"));
    }catch(e){setNote(tr(lang,"video.failed"));}
    setRec(false);
  };
  const p=pages[idx]||{};
  return(
    <div className="yl-story">
      <Confetti fire={done}/>
      <div className="yl-story-bars">{pages.map((_,i)=><span key={i} className={"yl-story-bar"+(i<idx?" done":i===idx?" now":"")}><span className="yl-story-bar-fill" style={i===idx&&!done?{animationDuration:"4.6s"}:undefined}/></span>)}</div>
      <button className="yl-story-back yl-noprint" onClick={onBack}>‹ {tr(lang,"story.back")}</button>
      <div className={"yl-story-page"+(p.photo?" has-photo":"")} key={idx}>
        {p.photo&&<img className="yl-story-img" src={p.photo} alt=""/>}
        {!p.photo&&<div className="yl-story-emoji">{p.emoji||"✨"}</div>}
        <p className="yl-story-kicker">{p.kicker||""}</p>
        {p.num!=null&&<div className="yl-story-num"><CountUp key={idx} value={p.num} decimals={p.decimals||0} dur={1100}/>{p.suffix&&<small>{p.suffix}</small>}</div>}
        {p.head&&<h3 className="yl-story-head">{p.head}</h3>}
        {p.label&&<p className="yl-story-label">{p.label}</p>}
        {(p.lines||[]).map((l,i)=><p key={i} className="yl-story-line">{l}</p>)}
      </div>
      <div className="yl-story-tap left" onClick={()=>setIdx(i=>Math.max(0,i-1))}/>
      <div className="yl-story-tap right" onClick={()=>{if(idx<last)setIdx(idx+1);}}/>
      {idx>=last&&<button className="yl-story-finish yl-noprint" onClick={onBack}>{tr(lang,"story.back")}</button>}
      <p className="yl-story-brand">🐾 {tr(lang,"brand.footer")} · LOALIFE {year}</p>
      {canRec&&<button className="yl-story-save yl-noprint" disabled={rec} onClick={saveStoryVideo}>{rec?"● "+tr(lang,"video.recording"):"🎬 "+tr(lang,"video.save")}</button>}
      {note&&<p className="yl-story-note">{note}</p>}
    </div>
  );
};
// ===== 写真スライドショー＋動画保存 =====
const SlideMaker=({slides,title,lang,onClose})=>{
  const seq=useMemo(()=>[{type:"title"},...slides.map(s=>({type:"photo",...s})),{type:"end"}], [slides]);
  const[idx,setIdx]=useState(0);
  const[playing,setPlaying]=useState(true);
  const[rec,setRec]=useState(false);
  const[recNote,setRecNote]=useState("");
  const canRec=typeof MediaRecorder!=="undefined";
  const DUR=2600;
  useEffect(()=>{
    if(!playing||rec)return;
    if(idx>=seq.length-1)return;
    const tm=setTimeout(()=>setIdx(i=>Math.min(seq.length-1,i+1)),seq[idx].type==="photo"?DUR:2000);
    return()=>clearTimeout(tm);
  },[idx,playing,seq,rec]);
  const cur=seq[idx];
  const saveVideo=async()=>{
    if(!canRec||rec)return;
    setRec(true);setRecNote(tr(lang,"video.recording"));
    try{
      const W=720,H=1280;const cv=document.createElement("canvas");cv.width=W;cv.height=H;
      const ctx=cv.getContext("2d");
      const imgs=await Promise.all(seq.map(async(s)=>{
        if(s.type!=="photo")return null;
        return await new Promise(res=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>res(null);im.src=s.src;});
      }));
      const stream=cv.captureStream(30);
      const mime=["video/mp4;codecs=avc1","video/mp4","video/webm;codecs=vp9","video/webm"].find(m=>{try{return MediaRecorder.isTypeSupported(m);}catch(e){return false;}})||"";
      const mr=new MediaRecorder(stream,mime?{mimeType:mime,videoBitsPerSecond:6000000}:{videoBitsPerSecond:6000000});
      const chunks=[];mr.ondataavailable=e=>{if(e.data&&e.data.size)chunks.push(e.data);};
      const stopped=new Promise(r=>{mr.onstop=r;});
      const drawCard=(big,small)=>{
        const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,"#2B2118");g.addColorStop(1,"#57402A");ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
        ctx.fillStyle="#FFE9A8";ctx.font="700 92px sans-serif";ctx.textAlign="center";ctx.fillText("🐾",W/2,H/2-120);
        ctx.fillStyle="#FFF7E8";ctx.font="800 54px sans-serif";
        const words=String(big||"");const max=12;let line1=words,line2="";
        if(words.length>max){line1=words.slice(0,max);line2=words.slice(max);}
        ctx.fillText(line1,W/2,H/2+10);if(line2)ctx.fillText(line2,W/2,H/2+84);
        if(small){ctx.fillStyle="#F3D9B0";ctx.font="600 34px sans-serif";ctx.fillText(small,W/2,H/2+170);}
        ctx.textAlign="left";
      };
      const drawPhoto=(im,cap,prog,alt)=>{
        ctx.fillStyle="#14100C";ctx.fillRect(0,0,W,H);
        if(im){
          const sc=(alt?1.14-0.12*prog:1.0+0.12*prog);
          const iw=im.width,ih=im.height;const base=Math.max(W/iw,H/ih)*sc;
          const dw=iw*base,dh=ih*base;const dx=(W-dw)/2+(alt?14*prog:-14*prog);const dy=(H-dh)/2;
          ctx.drawImage(im,dx,dy,dw,dh);
        }
        const g=ctx.createLinearGradient(0,H-300,0,H);g.addColorStop(0,"rgba(10,6,3,0)");g.addColorStop(1,"rgba(10,6,3,0.72)");ctx.fillStyle=g;ctx.fillRect(0,H-300,W,300);
        if(cap){ctx.fillStyle="#FFF";ctx.font="700 38px sans-serif";ctx.fillText(cap,36,H-64, W-72);}
        ctx.fillStyle="rgba(255,255,255,0.85)";ctx.font="600 26px sans-serif";ctx.fillText("🐾 LOALIFE",36,56);
      };
      mr.start(200);
      const per=seq.map(s=>s.type==="photo"?DUR:2000);
      const total=per.reduce((a,b)=>a+b,0);const t0=performance.now();
      await new Promise(res=>{
        const frame=(now)=>{
          const el=now-t0;
          if(el>=total){res();return;}
          let acc=0,ci=0;while(ci<seq.length-1&&el>acc+per[ci]){acc+=per[ci];ci++;}
          const prog=Math.min(1,(el-acc)/per[ci]);const s=seq[ci];
          if(s.type==="title")drawCard(title,tr(lang,"video.titleSub"));
          else if(s.type==="end")drawCard(tr(lang,"video.endBig"),tr(lang,"brand.footer"));
          else drawPhoto(imgs[ci],s.cap,prog,ci%2===1);
          requestAnimationFrame(frame);
        };
        requestAnimationFrame(frame);
      });
      mr.stop();await stopped;
      const blob=new Blob(chunks,{type:mr.mimeType||"video/webm"});
      const ext=(mr.mimeType||"").includes("mp4")?"mp4":"webm";
      const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`loalife-movie-${Date.now()}.${ext}`;document.body.appendChild(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(a.href),4000);
      setRecNote(tr(lang,"video.saved"));
    }catch(e){setRecNote(tr(lang,"video.failed"));}
    setRec(false);
  };
  return(
    <div className="yl-overlay yl-slide-ov" onClick={onClose}>
      <div className="yl-slide" onClick={e=>e.stopPropagation()}>
        <div className="yl-slide-stage">
          {cur.type==="title"&&<div className="yl-slide-card"><div className="yl-slide-paw">🐾</div><h3 className="yl-slide-title">{title}</h3><p className="yl-slide-sub">{tr(lang,"video.titleSub")}</p></div>}
          {cur.type==="photo"&&<div className="yl-slide-photo" key={idx}><img src={cur.src} alt="" className={"yl-slide-img "+(idx%2?"kb2":"kb1")}/><div className="yl-slide-shade"/><span className="yl-slide-logo">🐾 LOALIFE</span>{cur.cap&&<p className="yl-slide-cap">{cur.cap}</p>}</div>}
          {cur.type==="end"&&<div className="yl-slide-card"><div className="yl-slide-paw">🐾</div><h3 className="yl-slide-title">{tr(lang,"video.endBig")}</h3><p className="yl-slide-sub">{tr(lang,"brand.footer")}</p></div>}
          <div className="yl-slide-bars">{seq.map((_,i)=><span key={i} className={"yl-slide-bar"+(i<idx?" done":i===idx?" now":"")}/>)}</div>
        </div>
        <div className="yl-slide-ctrls yl-noprint">
          <button className="yl-slide-btn" onClick={()=>setPlaying(p=>!p)}>{playing?"⏸":"▶"}</button>
          <button className="yl-slide-btn wide" disabled={!canRec||rec} onClick={saveVideo}>{rec?"● "+tr(lang,"video.recording"):"🎬 "+tr(lang,"video.save")}</button>
          <button className="yl-slide-btn" onClick={onClose}>✕</button>
        </div>
        {!canRec&&<p className="yl-slide-note">{tr(lang,"video.unsupported")}</p>}
        {recNote&&<p className="yl-slide-note">{recNote}</p>}
      </div>
    </div>
  );
};

