  if(hasPets&&hasPersons){const fam=DISASTER_STOCK_DEFAULTS_FAMILY;const pet=DISASTER_STOCK_DEFAULTS.filter(d=>!fam.some(f=>f.key===d.key));return [...fam,...pet].map((d,i)=>({id:"ds"+i,key:d.key,cat:d.cat,done:false,bought:"",expiry:""}));}
