const PERSON_EMOJIS_BY_TYPE={baby:["👶"],child:["👧","🧒","👦"],adult:["👩","👨","🧑"],senior:["👵","👴","🧓"]};
const personEmojisFor=(pt)=>PERSON_EMOJIS_BY_TYPE[pt]||PERSON_EMOJIS;
