// ライフログ・カレンダー用：各アイテムが「どの日に紐づくか」を1つに正規化する。
//  予定/ケア=dueDate、ストック=購入日(lastBought)、思い出=date、ルーティン=実施日(doneDate)。
//  誕生日(bday)は毎年くりかえしなので日付軸では別扱い（null）。
function itemDate(it){
  if(!it)return null;
  if(it.type==="memory")return it.date||null;
  if(it.type==="supply")return it.lastBought||null;
  if(it.type==="routine")return it.doneDate||null;
  if(it.type==="toilet")return it.date||null;
  if(it.type==="bday")return null;
  if(it.date)return it.date;
  return it.dueDate||null;
}
// ケア種別ごとの日付ラベル（表示のみ。保存先は常に dueDate のまま・データ構造は不変）。
// 健康系（ワクチン・投薬等）は「実施日」、受診系は「受診日」、それ以外は「期限」。
const careDateLabel=(k)=>tr(APP_LANG,({vaccine:"sched.dateDone",rabies:"sched.dateDone",filaria:"sched.dateDone",med:"sched.dateDone",trim:"sched.dateDone",groom:"sched.dateDone",daycare:"sched.dateDate",checkup:"sched.dateVisit",hospital:"sched.dateVisit",dental:"sched.dateVisit"}[k]||"sched.dateDue"));
// カレンダー区分（色・アイコン）。予定/ケア/ストック/思い出。
function calCategory(it){
  if(!it)return"event";
  if(it.type==="memory")return"memory";
  if(it.type==="supply")return"supply";
  if(it.type==="care")return"care";
  if(it.type==="routine")return"routine";
  if(["walk","feed","health","diary","nursing","expense","period"].includes(it.type))return"routine";
  return"event";
}
// 日々の記録（タイトルを持たないタイプ）のカレンダー表示名。
const REC_LABEL_KEY={walk:"rectype.walk",feed:"rectype.feed",health:"rectype.health",diary:"rectype.diary",nursing:"rectype.nursing",expense:"rectype.expense",period:"rectype.period"};
function recordLabel(it){const k=it&&REC_LABEL_KEY[it.type];return k?tr(APP_LANG,k):"";}
// ─── 予定カテゴリ（大項目）と複数日予定 ─────────────────────────────
// カテゴリは「予定側」（type=event / care）の分類。プリセット7種は固定で色だけ
// 変更できる。カスタムは最大5件まで追加でき、定義は端末ローカル
// （loalife-calcats-v1）に保存する（端末設定の扱い。本体データには混ぜない）。
// アイテム側は evCat にキー（プリセットkeyまたはカスタムid）を保持するだけ。
// evCat が無い旧データは「予定」として表示する（読み取り時の寄せのみ・非破壊）。
const CALCAT_PRESETS=[
  {key:"work",emoji:"💼",color:"#5B7A9E"},
  {key:"plan",emoji:"📅",color:"#C77A2E"},
  {key:"social",emoji:"🍻",color:"#D9A441"},
  {key:"medical",emoji:"🏥",color:"#B23A48"},
  {key:"beauty",emoji:"💇",color:"#E29CC6"},
  {key:"travel",emoji:"✈️",color:"#3E8E8E"},
  {key:"other",emoji:"✨",color:"#8A8178"},
];
const CALCAT_MAX_CUSTOM=5;
const CALCATS_KEY="loalife-calcats-v1";
// 保存値の防御的サニタイズ（壊れた値でも既定に落とす・未知の色上書きはプリセット分のみ）。
const sanitizeCalCats=(raw)=>{
  const out={custom:[],colors:{}};
  if(!raw||typeof raw!=="object")return out;
  if(Array.isArray(raw.custom))raw.custom.slice(0,CALCAT_MAX_CUSTOM).forEach(c=>{
    if(c&&typeof c.id==="string"&&c.id&&typeof c.name==="string"&&c.name.trim())out.custom.push({id:c.id,name:c.name,emoji:typeof c.emoji==="string"&&c.emoji?c.emoji:"🏷️",color:typeof c.color==="string"&&c.color?c.color:"#E39A5C"});
  });
  if(raw.colors&&typeof raw.colors==="object")Object.keys(raw.colors).forEach(k=>{if(CALCAT_PRESETS.some(p=>p.key===k)&&typeof raw.colors[k]==="string"&&raw.colors[k])out.colors[k]=raw.colors[k];});
  return out;
};
const evCatOf=(it)=>(it&&typeof it.evCat==="string"&&it.evCat)?it.evCat:"plan";
// 日々の記録（タイトルを持たない日常ログ＋ルーティンの実施）。カレンダー日表示では
// 予定の後ろに「{name}の記録 {n}件」として畳む対象。それ以外は予定側として出す。
const DAILY_RECORD_TYPES=["walk","feed","health","diary","nursing","expense","period","toilet"];
const isDailyRecord=(it)=>!!it&&(DAILY_RECORD_TYPES.includes(it.type)||it.type==="routine");
// 予定の期間。endDate が開始日より後にある時だけ複数日として扱う（同日・逆転は単日）。
const itemSpan=(it)=>{const s=itemDate(it);if(!s)return null;const e=(it&&typeof it.endDate==="string"&&it.endDate>s)?it.endDate:s;return{start:s,end:e};};
const spanCovers=(it,dayIso)=>{const sp=itemSpan(it);return!!sp&&typeof dayIso==="string"&&dayIso>=sp.start&&dayIso<=sp.end;};
// 日数差は既存の daysBetween（ファイル冒頭）を使う。
const WEEKDAYS_JA=["日","月","火","水","木","金","土"];
const MON_EN=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const fmtMonthDay=(s)=>{if(!s||typeof s!=="string")return"";const[,m,d]=s.split("-").map(Number);return`${m}月${d}日`;};
const mmdd=(s)=>s?s.slice(5):""; // "MM-DD"
const dowOf=(iso)=>{if(!iso)return 0;const[y,m,d]=iso.split("-").map(Number);return new Date(y,m-1,d).getDay();};
// CSV・表示用の繰り返しラベル（日本語固定。画面表示は repeatTextOf を使う）
const repeatCsvLabel=(x)=>{if(!x||!x.repeat||x.repeat==="none")return"";if(x.repeat==="weekly"){const days=repeatDaysOf(x);if(days){if(days.length===5&&REPEAT_WEEKDAYS.every(d=>days.indexOf(d)>=0))return"平日のみ";if(days.length===2&&REPEAT_WEEKEND.every(d=>days.indexOf(d)>=0))return"週末のみ";return"毎週 "+days.map(d=>WEEKDAYS_JA[d]).join("・");}return"毎週";}return(REPEATS.find(r=>r.key===x.repeat)||{}).label||"";};
// 写真は複数可。新形式は item.photos=[id...]、旧形式は photo:true（IDBキーは photo:<item.id>）。
const photoIdsOf=(it)=>it&&Array.isArray(it.photos)&&it.photos.length?it.photos:(it&&it.photo?[it.id]:[]);
const firstPhotoId=(it)=>{const a=photoIdsOf(it);return a.length?a[0]:null;};
// ─── 記録者（家族共有：誰が記録したか） ─────────────────────────────
// 記録者情報はアイテム自身に持つ（byUid = 記録したアカウントの uid、byName = その時点の
// 表示名のスナップショット）。users/{uid} は本人のみ読み取り可のルールのため、他の家族の
// 表示名をアカウント側から引くことはできない。家族ノートの author と同じ
// 「記録に名前を埋める」方式に揃える。旧データ（byUid/byName が無い共有記録）は
// ownerUid（Firestore 保存時に必ず書かれる作成者 uid）を記録者として扱い、
// それも無いものは記録者なし（表示側で「家族」にフォールバックする）。
const recorderUidOf=(it)=>{if(!it||typeof it!=="object")return null;return it.byUid||it.ownerUid||null;};
// ISO日付（YYYY-MM-DD）の正午のミリ秒。日付だけの記録の並び順用（TZずれで日が動かないよう正午）。
const dayNoonMs=(s)=>{if(!s||typeof s!=="string")return 0;const[y,m,d]=s.split("-").map(Number);if(!y||!m||!d)return 0;const dt=new Date(y,m-1,d,12);return dt.getFullYear()===y&&dt.getMonth()===m-1&&dt.getDate()===d?dt.getTime():0;};
// 家族フィードの対象種別（単発の記録ログ）。ケア/予定の完了・服薬は別経路で足す。
const FAM_FEED_LOG_TYPES=["walk","feed","toilet","diary","health","memory","nursing","milestone"];
// 家族の記録フィードを組み立てる純粋関数。
//   items: 全アイテム / sharedIds: 「共有」設定のメンバーIDの Set（この子たちの記録だけが対象）
//   sinceIso..todayIso の日付範囲（ISO文字列の比較）で絞り、新しい順に limit 件まで。
// 各エントリ: {key,space,kind,date,ts,hasTime,seg,itemId,title,foodName,name,byUid,byName}
//   seg は遷移先セグメント（ログ系="record"、ケア/予定の完了="manage"）。
//   記録者は byUid/byName。服薬は takenBy[日付]、ケア完了は lastBy* を優先し、
//   無ければアイテムの記録者にフォールバックする（旧データでも表示が破綻しない）。
//   hasTime は ts が実時刻（createdAt 等）由来の時だけ true。日付のみ由来の正午は
//   時刻として表示しない（実態と違う時刻を見せないため）。
const buildFamilyFeed=(items,sharedIds,sinceIso,todayIso,limit=40)=>{
  const inWin=(d)=>typeof d==="string"&&d>=sinceIso&&d<=todayIso;
  const out=[];
  (items||[]).forEach(it=>{
    if(!it||!sharedIds||!sharedIds.has(it.space))return;
    const byUid=recorderUidOf(it),byName=it.byName||null;
    if(FAM_FEED_LOG_TYPES.includes(it.type)){
      if(!inWin(it.date))return;
      let ts=it.createdAt||0,hasTime=!!it.createdAt;
      if(it.type==="walk"){ts=it.start||it.createdAt||0;hasTime=!!(it.start||it.createdAt);}
      if(!ts){ts=dayNoonMs(it.date);hasTime=false;}
      out.push({key:"lg:"+it.id,space:it.space,kind:it.type,date:it.date,ts,hasTime,seg:"record",itemId:it.id,title:it.title||"",foodName:it.foodName||"",name:"",byUid,byName});
      return;
    }
    if(it.type==="medcourse"){
      (it.taken||[]).forEach(d=>{
        if(!inWin(d))return;
        const tb=(it.takenBy&&typeof it.takenBy==="object")?it.takenBy[d]:null;
        // 服薬は「その日に押した人」が分かる場合だけ名前を持つ。takenBy が無い旧データで
        // コース作成者の名前を出すと「その人があげた」ように見えてしまう（実態と不一致）
        // ため、記録者なし（表示側で「家族」）にする。
        out.push({key:"med:"+it.id+":"+d,space:it.space,kind:"medcourse",date:d,ts:(tb&&tb.at)||dayNoonMs(d),hasTime:!!(tb&&tb.at),seg:"record",itemId:it.id,title:"",foodName:"",name:it.name||"",byUid:(tb&&tb.uid)||null,byName:(tb&&tb.name)||null});
      });
      return;
    }
    if(it.type==="care"||it.type==="event"){
      // 周期ケアの完了は lastDone / lastDoneAt、単発の完了は done + completedAt が根拠。
      if(it.lastDone&&inWin(it.lastDone)){
        out.push({key:"done:"+it.id+":"+it.lastDone,space:it.space,kind:"done",date:it.lastDone,ts:it.lastDoneAt||dayNoonMs(it.lastDone),hasTime:!!it.lastDoneAt,seg:"manage",itemId:it.id,title:it.title||"",foodName:"",name:"",byUid:it.lastByUid||byUid,byName:it.lastByName||byName});
      }else if(it.done&&it.completedAt){
        const d=isoOf(it.completedAt);
        if(inWin(d))out.push({key:"done:"+it.id+":"+d,space:it.space,kind:"done",date:d,ts:it.completedAt,hasTime:true,seg:"manage",itemId:it.id,title:it.title||"",foodName:"",name:"",byUid:it.lastByUid||byUid,byName:it.lastByName||byName});
      }
    }
  });
  out.sort((a,b)=>(b.ts-a.ts)||(a.key<b.key?-1:a.key>b.key?1:0));
  return out.slice(0,limit);
};
// ─── 写真の家族共有（transport 抽象化） ─────────────────────────────
// 共有コピーの仕様は公開名刺と同じ（最大辺 480px・JPEG 品質 0.75）。端末内の原本は
// そのまま残し、共有用に小さくしたコピーだけを送る（文案の「共有用に小さくした画像」）。
// 経路は Firestore 埋め込み（写真1枚＝1ドキュメント、data に data URL 文字列）。
// Firebase Storage は Spark プランでは使えない（2024年9月のポリシー変更で Blaze が
// 必須になり、このプロジェクトにはバケット自体が存在しない）ため、無料で確実に動く
// この方式を採用する。将来 Blaze 化して Storage へ移す場合は、photoShareTransport の
// 中身（get/put/remove/listIds）を差し替えるだけでよい（呼び出し側は不変）。
const PHOTO_SHARE_MAX_DIM=480;
const PHOTO_SHARE_QUALITY=0.75;
const PHOTO_SHARE_MAX_PER_MEMBER=300; // メンバーごとの共有上限（新しい順）。上限外の写真は端末内のみ。
const PHOTO_SHARE_MAX_CHARS=680000;   // ルール側の上限（700,000文字）より少し内側で止める安全圏。
// data URL の同一性判定用フィンガープリント（長さ＋疎なサンプルのハッシュ）。
const photoShareFingerprint=(s)=>{if(typeof s!=="string"||!s)return "";let h=0;const n=s.length;const step=Math.max(1,Math.floor(n/512));for(let i=0;i<n;i+=step){h=((h*31)+s.charCodeAt(i))>>>0;}return n+":"+h.toString(36);};
// 写真共有の対象メンバーか（「わたし」と「自分のみ」は共有しない＝現行の共有境界を厳密に維持）。
const photoShareTarget=(m)=>!!m&&m.id!=="me"&&visOf(m)==="household";
// メンバーの共有対象写真を「参照順」で一意に並べる：プロフィール写真→ポスター写真→
// 記録の写真（新しい順）。cap を渡すとその件数で切る（上限外は端末内のみになる）。
const sharedPhotoIdsForMember=(member,items,cap)=>{
  const seen=new Set();const out=[];
  const push=(pid)=>{if(pid&&!seen.has(pid)){seen.add(pid);out.push(pid);}};
  if(member){push(member.avatar);(member.posterPhotos||[]).forEach(push);}
  const mid=member&&member.id;
  [...(items||[])].filter(x=>x&&x.space===mid).sort((a,b)=>((b.createdAt||0)-(a.createdAt||0))).forEach(x=>photoIdsOf(x).forEach(push));
  return cap?out.slice(0,cap):out;
};
// 写真 transport（現行 = Firestore 埋め込み）。配置は households/{hid}/members/{mid}/photos/{pid}。
const photoShareTransport={
  ref:(db,hid,mid,pid)=>doc(db,"households",hid,"members",mid,"photos",pid),
  col:(db,hid,mid)=>collection(db,"households",hid,"members",mid,"photos"),
  get:async(db,hid,mid,pid)=>{const s=await getDoc(photoShareTransport.ref(db,hid,mid,pid));return s.exists()?s.data():null;},
  put:async(db,hid,mid,pid,payload)=>{await setDoc(photoShareTransport.ref(db,hid,mid,pid),payload,{merge:true});},
  remove:async(db,hid,mid,pid)=>{await deleteDoc(photoShareTransport.ref(db,hid,mid,pid));},
  listIds:async(db,hid,mid)=>{const s=await getDocs(photoShareTransport.col(db,hid,mid));return s.docs.map(d=>d.id);},
};
