// 引数はメンバー(または null=自分)。人は personType(大人/子ども/高齢者)で候補を切替。
const choreTemplatesFor=(m)=>{
  if(!m)return CHORE_TPL_ME;
  if(m.kind==="pet"){
    // 種で出し分け：犬に猫砂替えは出さない／その他ペットに毛・耳・爪のお手入れ系は出さない（猫は全候補）。
    if(m.species==="dog")return CHORE_TPL_PET.filter(t=>t.title!=="トイレ砂替え");
    if(m.species==="cat")return CHORE_TPL_PET;
    return CHORE_TPL_PET.filter(t=>!["シャンプー","爪切り","ブラッシング","耳そうじ"].includes(t.title));
  }
  if(m.kind==="person"){const pt=m.personType||"child";return pt==="senior"?CHORE_TPL_SENIOR:pt==="adult"?CHORE_TPL_ADULT:pt==="baby"?CHORE_TPL_BABY:CHORE_TPL_CHILD;}
  return CHORE_TPL_ME;
};

