const foodUnitLabel=(k)=>{if(k==="g"||k==="ml")return k;const M={ja:{serving:"回",grain:"粒",piece:"個",animal:"匹"},en:{serving:"srv",grain:"pcs",piece:"pc",animal:"pcs"},es:{serving:"toma",grain:"gr",piece:"ud",animal:"uds"},zh:{serving:"次",grain:"粒",piece:"个",animal:"只"}};return (M[APP_LANG]||M.ja)[k]||k||"";};
