function dueStatus(item){if(!item.dueDate)return null;if(item.done)return{label:tr(APP_LANG,"status.done"),tone:"doneChip"};const d=daysUntil(item.dueDate);if(d>3)return{label:fmtDate(item.dueDate),tone:"normal"};if(d>0)return{label:tr(APP_LANG,"status.inDays",{d}),tone:"soon"};if(d===0)return{label:tr(APP_LANG,"status.today"),tone:"today"};if(item.type==="dream")return{label:tr(APP_LANG,"status.dreamOver"),tone:"gentleOver"};if(isCyclic(item))return{label:tr(APP_LANG,"status.overdue"),tone:"careOver"};return{label:fmtDate(item.dueDate),tone:"normal"};}
// ケアの3状態：未対応(赤)／予定済み(黄)／完了(緑)。打ち消し線＋期限切れの読めない状態を1目で。
function careState(item){
  if(item.done)return{label:tr(APP_LANG,"care.done"),tone:"done"};
  const renew=isRenewCare(item);
  if(isOverdue(item)){const d=-daysUntil(item.dueDate);return{label:renew?tr(APP_LANG,"care.overdueRenew",{d}):tr(APP_LANG,"care.overdueTodo",{d}),tone:"todo"};}
  if(item.dueDate){const d=daysUntil(item.dueDate);
    if(d<0)return{label:tr(APP_LANG,"care.plannedDate",{date:fmtDate(item.dueDate)}),tone:"planned"};
    if(renew){
      if(d===0)return{label:tr(APP_LANG,"care.dueToday"),tone:"planned"};
      if(d<=30)return{label:tr(APP_LANG,"care.dueInDays",{d}),tone:"planned"};
      return{label:tr(APP_LANG,"care.validDays",{d}),tone:"doneChip"};
    }
    return{label:d===0?tr(APP_LANG,"care.doToday"):tr(APP_LANG,"care.plannedDays",{d}),tone:"planned"};
  }
  return{label:tr(APP_LANG,"care.planned"),tone:"planned"};
}
// 更新型ケア（狂犬病・ワクチン等）の有効期限までの残り。証明書セルなどの小さな表示用。
function renewLeft(item){
  if(!isRenewCare(item)||!item.dueDate)return null;
  const d=daysUntil(item.dueDate);if(d==null)return null;
  if(d<0)return{txt:tr(APP_LANG,"renew.expired",{n:-d}),tone:"over"};
  if(d===0)return{txt:tr(APP_LANG,"renew.today"),tone:"soon"};
  if(d<=30)return{txt:tr(APP_LANG,"renew.left",{n:d}),tone:"soon"};
  return{txt:tr(APP_LANG,"renew.left",{n:d}),tone:"ok"};
}

function daysUntilBirthday(birthday) {
  if (!birthday||typeof birthday!=="string") return null;
  const [,bm,bd] = birthday.split("-").map(Number);
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  let next = new Date(today.getFullYear(), bm - 1, bd);
  if (next < today) next.setFullYear(next.getFullYear() + 1);
  return Math.round((next - today) / 86400000);
}
// 記念日（誕生日・うちの子記念日）までの日数。daysUntilBirthday と同じ計算。
const daysUntilAnniv = daysUntilBirthday;
// その日付から今回の記念日で何年目になるか（年が分かる場合のみ。不明なら null）
function yearsSinceAnniv(dateStr) {
  if (!dateStr) return null;
  const [y, m, d] = dateStr.split("-").map(Number);
  if (!y || y < 1900) return null;
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  let years = today.getFullYear() - y;
  // 今年の記念日がまだ来ていなければ、次に迎えるのは years 年目
  const thisYear = new Date(today.getFullYear(), m - 1, d);
  if (thisYear < today) years += 1; // 既に過ぎた→次回は+1年
  return years;
}
// 満年齢／経過周年（西暦がある場合のみ。年不明＝"0000"や未入力は null）
function ageNow(dateStr){
  if(!dateStr)return null;
  const[y,m,d]=dateStr.split("-").map(Number);
  if(!y||y<1900)return null;
  const now=new Date();
  let a=now.getFullYear()-y;
  const passed=(now.getMonth()+1>m)||(now.getMonth()+1===m&&now.getDate()>=d);
  if(!passed)a-=1;
  return a<0?null:a;
}
// お迎えから今日までの日数（西暦がある場合のみ）。何日一緒に過ごしたか。
function daysTogether(dateStr,endStr){
  if(!dateStr)return null;
  const[y,m,d]=dateStr.split("-").map(Number);
  if(!y||y<1900)return null;
  const start=new Date(y,m-1,d);
  let end;
  if(endStr){const[ey,em,ed]=endStr.split("-").map(Number);if(ey&&ey>=1900)end=new Date(ey,em-1,ed);}
  if(!end){const now=new Date();end=new Date(now.getFullYear(),now.getMonth(),now.getDate());}
  const days=Math.floor((end-start)/86400000);
  return days>=0?days:null;
}
// 生後の月齢（西暦がある場合のみ）。子犬・子猫の成長を月単位で。
function monthsOld(dateStr){
  if(!dateStr||typeof dateStr!=="string")return null;
  const[y,m,d]=dateStr.split("-").map(Number);
  if(!y||y<1900)return null;
  const now=new Date();
  let months=(now.getFullYear()-y)*12+(now.getMonth()+1-m);
  if(now.getDate()<d)months-=1;
  return months<0?null:months;
}
// 公開ページ（名刺・サマリー・ポスター等）用の年齢ラベル。西暦なし（"0000"）・不正な日付では年齢を出さない（ageLabel/monthsOld と同じ規則を、文字列ベースで厳密に判定する）
function pubAgeLabel(birthday,lang){
  if(!birthday||typeof birthday!=="string")return "";
  const y=Number(birthday.split("-")[0]);if(!y||y<1900)return "";
  const b=new Date(birthday);if(isNaN(b))return "";
  const n=new Date();let yy=n.getFullYear()-b.getFullYear();let mo=n.getMonth()-b.getMonth();
  if(n.getDate()<b.getDate())mo--;if(mo<0){yy--;mo+=12;}
  if(yy>0)return tr(lang,"petpage.ageY",{y:yy});
  if(mo>0)return tr(lang,"petpage.ageM",{m:mo});
  return tr(lang,"petpage.ageNew");
}
// 年齢の表示ラベル：1歳未満は月齢、2歳未満は「X歳Yヶ月」、以降は「X歳」。西暦なしは空。
function ageLabel(dateStr){
  const m=monthsOld(dateStr);if(m==null)return"";
  const L=APP_LANG;
  const mo=(n)=>L==="ja"?`${n}ヶ月`:L==="zh"?`${n}个月`:L==="es"?(n===1?"1 mes":`${n} meses`):`${n} mo`;
  const yr=(n)=>L==="ja"?`${n}歳`:L==="zh"?`${n}岁`:L==="es"?(n===1?"1 año":`${n} años`):(n===1?"1 yr":`${n} yrs`);
  if(m<12)return mo(m);
  const yrs=Math.floor(m/12),rem=m%12;
  if(yrs<2&&rem>0)return L==="ja"?`${yrs}歳${rem}ヶ月`:L==="zh"?`${yrs}岁${rem}个月`:L==="es"?`${yr(yrs)} ${mo(rem)}`:`${yr(yrs)} ${mo(rem)}`;
  return yr(yrs);
}

// ある日付時点の年齢ラベル（成長記録で「その時何歳だったか」を表示）。
function ageAtLabel(birthStr,atStr){
  if(!birthStr||!atStr)return"";
  const[by,bm,bd]=birthStr.split("-").map(Number);
  const[ay,am,ad]=atStr.split("-").map(Number);
  if(!by||by<1900||!ay)return"";
  let months=(ay-by)*12+(am-bm);if(ad<bd)months-=1;
  if(months<0)return"";
  if(months<12)return`${months}ヶ月`;
  const yrs=Math.floor(months/12),rem=months%12;
  if(yrs<3)return rem>0?`${yrs}歳${rem}ヶ月`:`${yrs}歳`;
  return`${yrs}歳`;
}

// 招待コード：暗号学的乱数・紛らわしい文字を除外（I/O/0/1 等）。列挙はルールで禁止（get のみ）。
function genCode() {
  const CS = "ABCDEFGHJKMNPQRSTUVWXYZ23456789"; // 31 chars, no I/O/0/1/L
  const n = 8, a = new Uint8Array(n);
  try { (crypto && crypto.getRandomValues) ? crypto.getRandomValues(a) : a.forEach((_, i) => { a[i] = Math.floor(Math.random() * 256); }); }
  catch (e) { for (let i = 0; i < n; i++) a[i] = Math.floor(Math.random() * 256); }
  let s = ""; for (let i = 0; i < n; i++) s += CS[a[i] % CS.length];
  return s; // 31^8 ≈ 8.5e11
}
// サマリー共有リンクのID：医療寄りの情報を渡すため、名刺（20文字）より長い推測困難なランダム24文字。URL ?sum=<id> で使う。
function genSummaryId() {
  const CS = "ABCDEFGHJKMNPQRSTUVWXYZ23456789abcdefghjkmnpqrstuvwxyz"; // 紛らわしい文字を除外
  const n = 24, a = new Uint8Array(n);
  try { (crypto && crypto.getRandomValues) ? crypto.getRandomValues(a) : a.forEach((_, i) => { a[i] = Math.floor(Math.random() * 256); }); }
  catch (e) { for (let i = 0; i < n; i++) a[i] = Math.floor(Math.random() * 256); }
  let s = ""; for (let i = 0; i < n; i++) s += CS[a[i] % CS.length];
  return s;
}
// 迷子ポスター公開ページのID：連絡先を含むため、サマリーと同じ推測困難なランダム24文字。URL ?lost=<id> で使う。
function genPosterId() {
  const CS = "ABCDEFGHJKMNPQRSTUVWXYZ23456789abcdefghjkmnpqrstuvwxyz"; // 紛らわしい文字を除外
  const n = 24, a = new Uint8Array(n);
  try { (crypto && crypto.getRandomValues) ? crypto.getRandomValues(a) : a.forEach((_, i) => { a[i] = Math.floor(Math.random() * 256); }); }
  catch (e) { for (let i = 0; i < n; i++) a[i] = Math.floor(Math.random() * 256); }
  let s = ""; for (let i = 0; i < n; i++) s += CS[a[i] % CS.length];
  return s;
}
// 公開名刺のカードID：推測困難なランダム20文字（英数字）。URL ?card=<id> で使う。
function genCardId() {
  const CS = "ABCDEFGHJKMNPQRSTUVWXYZ23456789abcdefghjkmnpqrstuvwxyz"; // 紛らわしい文字を除外
  const n = 20, a = new Uint8Array(n);
  try { (crypto && crypto.getRandomValues) ? crypto.getRandomValues(a) : a.forEach((_, i) => { a[i] = Math.floor(Math.random() * 256); }); }
  catch (e) { for (let i = 0; i < n; i++) a[i] = Math.floor(Math.random() * 256); }
  let s = ""; for (let i = 0; i < n; i++) s += CS[a[i] % CS.length];
  return s;
}
// 推測困難な household ID（タイムスタンプは列挙可能なため廃止）。
function genId() {
  const a = new Uint8Array(16);
  try { (crypto && crypto.getRandomValues) ? crypto.getRandomValues(a) : a.forEach((_, i) => { a[i] = Math.floor(Math.random() * 256); }); }
  catch (e) { for (let i = 0; i < 16; i++) a[i] = Math.floor(Math.random() * 256); }
  return Array.from(a, b => b.toString(16).padStart(2, "0")).join("");
}

// ============================================================================
// 犬友だち名刺スキャン（MVP）— 独立モジュール。既存の members/items/schema とは非干渉。
//  - QR は画像からローカル読取り（jsQR 自己ホストを遅延ロード）。OCR は差し込み口のみ（今回は無効）。
//  - 外部送信なし。URL は厳密パース＋hostname 完全一致の許可リストで検証。
// ============================================================================
const DOGFRIENDS_ENABLED = true;
const DF_KEY = "loalife-dogfriends-v1";
// #6 書類ドキュメント：保存先は端末ローカルのみ（DOCS_KEY）。家族共有・クラウド
// バックアップ・写真共有のいずれにも載せない（comprehensive-analysis §④の原則）。
const DOCS_KEY = "loalife-docs-v1";
const DOC_KINDS_PERSON=[["insurance","🪪"],["maternal","📖"],["vaccine","💉"],["exam","🧾"],["prescription","💊"],["passport","🛂"],["mynumber","🔢"],["contract","📄"],["other","🗂"]];
const DOC_KINDS_PET=[["petlicense","🐾"],["vaccine","💉"],["exam","🧾"],["insurance","🪪"],["pedigree","📜"],["contract","📄"],["other","🗂"]];
const DF_IMG_PREFIX = "dogcard:"; // IndexedDB(photoStorage)上の名刺画像キー接頭辞
// OCR（任意・端末内）：tesseract.js(jpn_fast) を自己ホスト・遅延ロード。失敗しても手入力で完結。
//  名前・犬種などは推測補完せず、確実に抽出できるもの（URL/メール/電話）だけ候補化し、全文は参考表示。
const TESS_BASE = "/vendor/tesseract/";
let _tessLibP = null, _tessWorker = null;
function loadTesseractLib() {
  if (typeof window !== "undefined" && window.Tesseract) return Promise.resolve(window.Tesseract);
  if (_tessLibP) return _tessLibP;
  _tessLibP = new Promise((res, rej) => {
    try { const s = document.createElement("script"); s.src = TESS_BASE + "tesseract.min.js"; s.async = true;
      s.onload = () => (window.Tesseract ? res(window.Tesseract) : rej(new Error("tesseract-missing")));
      s.onerror = () => { _tessLibP = null; rej(new Error("tesseract-load-failed")); };
      document.head.appendChild(s); } catch (e) { _tessLibP = null; rej(e); }
  });
  return _tessLibP;
}
async function getTessWorker(onProgress) {
  if (_tessWorker) return _tessWorker;
  const T = await loadTesseractLib();
  _tessWorker = await T.createWorker("jpn", 1, { // OEM 1 = LSTM_ONLY
    workerPath: TESS_BASE + "worker.min.js",
    corePath: TESS_BASE,       // ディレクトリ指定：simd-lstm / lstm を自動選択
    langPath: TESS_BASE,       // jpn.traineddata を同梱（gzip:false＝CDNの転送時圧縮に任せ二重解凍を回避）
    gzip: false,
    logger: (m) => { try { onProgress && onProgress(m); } catch (e) {} },
  });
  return _tessWorker;
}
// 全文から「確実に取れるもの」だけ抽出（推測しない）。URL は許可リスト検証つき。
function extractCardFields(text) {
  const urls = [], emails = [], phones = [];
  const t = text || "";
  (t.match(/\bhttps?:\/\/[^\s"'<>）」】]+/gi) || []).forEach(u => { const p = parseSocialUrl(u); if (p.safe && !urls.some(x => x.url === p.url)) urls.push(p); });
  (t.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || []).forEach(e => { if (!emails.includes(e)) emails.push(e); });
  (t.match(/0\d[-(\s]?\d{1,4}[-)\s]?\d{2,4}[-\s]?\d{3,4}/g) || []).forEach(p => { const v = p.trim(); if (!phones.includes(v)) phones.push(v); });
  return { urls, emails, phones };
}
const OCR = {
  async recognize(dataUrl, onProgress) {
    const w = await getTessWorker(onProgress);
    const r = await w.recognize(dataUrl);
    const text = (r && r.data && r.data.text) || "";
    return { text, fields: extractCardFields(text) };
  },
};

// SNS 許可リスト（hostname の完全一致のみ。部分一致は使わない）。
const SNS_HOSTS = {
  "instagram.com": "Instagram", "www.instagram.com": "Instagram", "instagr.am": "Instagram",
  "tiktok.com": "TikTok", "www.tiktok.com": "TikTok", "vm.tiktok.com": "TikTok", "m.tiktok.com": "TikTok",
  "youtube.com": "YouTube", "www.youtube.com": "YouTube", "m.youtube.com": "YouTube", "youtu.be": "YouTube",
  "x.com": "X", "www.x.com": "X", "twitter.com": "X", "www.twitter.com": "X", "mobile.twitter.com": "X",
  "facebook.com": "Facebook", "www.facebook.com": "Facebook", "m.facebook.com": "Facebook",
  "line.me": "LINE", "page.line.me": "LINE", "lin.ee": "LINE",
  "threads.net": "Threads", "www.threads.net": "Threads",
};
// URL を厳密に検証。安全なスキーム(http/https)のみ許可し、hostname で対応プラットフォームを判定。
// 返り値: { safe, supported, platform, url, hostname }。safe=false は保存・オープン不可。
function parseSocialUrl(raw) {
  if (!raw || typeof raw !== "string") return { safe: false };
  const s = raw.trim();
  if (!s || s.length > 2000) return { safe: false };
  let u;
  try { u = new URL(s); } catch (e) { return { safe: false }; }
  if (u.protocol !== "https:" && u.protocol !== "http:") return { safe: false }; // javascript:/data: 等を拒否
  const host = (u.hostname || "").toLowerCase();
  const platform = SNS_HOSTS[host] || null;
  const url = u.protocol === "http:" ? ("https://" + u.host + u.pathname + u.search) : u.href; // https に正規化
  return { safe: true, supported: !!platform, platform: platform || "Other", url, hostname: host };
}

// ID/ハンドルからリンクを組み立てる（毎回 https:// を手打ちしなくて済むように）。
const SNS_BUILD = {
  Instagram: (h) => `https://www.instagram.com/${h}/`,
  X: (h) => `https://x.com/${h}`,
  TikTok: (h) => `https://www.tiktok.com/@${h}`,
  YouTube: (h) => `https://www.youtube.com/@${h}`,
  Threads: (h) => `https://www.threads.net/@${h}`,
  Facebook: (h) => `https://www.facebook.com/${h}`,
};
const SNS_PLATFORMS = ["Instagram", "X", "TikTok", "YouTube", "Threads", "Facebook", "URL"];
// platform＋入力（@id / URL どちらでも）から検証済みリンクを返す。
function buildSocialFromInput(platform, raw) {
  const s = (raw || "").trim();
  if (!s) return { safe: false, reason: "empty" };
  // URL をそのまま貼った場合
  if (/^https?:\/\//i.test(s)) return parseSocialUrl(s);
  // ドメイン直書き（例: instagram.com/loa, note.com/x）→ https を補って検証（TLDは限定しない）
  if (/^[\w.-]+\.[a-z]{2,}(\/|\?|$)/i.test(s)) return parseSocialUrl("https://" + s);
  // http(s) 以外のスキーム（javascript:/data: 等）は拒否
  if (/^[a-z][a-z0-9+.\-]*:/i.test(s)) return { safe: false, reason: "scheme" };
  // それ以外はハンドルとして扱う。URL モードはリンク必須。
  if (platform === "URL" || !SNS_BUILD[platform]) return { safe: false, reason: "needUrl" };
  const h = s.replace(/[@\s]/g, "").replace(/[^A-Za-z0-9._\-]/g, ""); // @と空白を除去し、使える文字だけに
  if (!h) return { safe: false, reason: "handle" }; // 日本語だけ等、ハンドルを作れない
  return parseSocialUrl(SNS_BUILD[platform](h));
}

// jsQR（自己ホスト）を必要時に1度だけ遅延ロード。CSP は script-src 'self' のまま適合。
let _jsqrPromise = null;
function loadJsQR() {
  if (typeof window !== "undefined" && window.jsQR) return Promise.resolve(window.jsQR);
  if (_jsqrPromise) return _jsqrPromise;
  _jsqrPromise = new Promise((resolve, reject) => {
    try {
      const sc = document.createElement("script");
      sc.src = "/vendor/jsqr.js"; sc.async = true;
      sc.onload = () => (window.jsQR ? resolve(window.jsQR) : reject(new Error("jsqr-missing")));
      sc.onerror = () => { _jsqrPromise = null; reject(new Error("jsqr-load-failed")); };
      document.head.appendChild(sc);
    } catch (e) { _jsqrPromise = null; reject(e); }
  });
  return _jsqrPromise;
}
// 画像 dataURL から QR を検出。1枚に複数QRがある場合に備え、全体＋4分割＋中央を走査して重複排除。
async function decodeQRCandidates(dataUrl) {
  const jsQR = await loadJsQR();
  const img = await new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = () => rej(new Error("img")); i.src = dataUrl; });
  let w = img.naturalWidth || img.width, h = img.naturalHeight || img.height;
  if (!w || !h) throw new Error("img-empty");
  const MAXD = 1400, sc = Math.min(1, MAXD / Math.max(w, h));
  const cw = Math.max(1, Math.round(w * sc)), ch = Math.max(1, Math.round(h * sc));
  const cv = document.createElement("canvas"); cv.width = cw; cv.height = ch;
  const ctx = cv.getContext("2d"); ctx.drawImage(img, 0, 0, cw, ch);
  const found = [], seen = new Set();
  const regions = [[0, 0, cw, ch], [0, 0, Math.ceil(cw / 2), Math.ceil(ch / 2)], [Math.floor(cw / 2), 0, Math.ceil(cw / 2), Math.ceil(ch / 2)], [0, Math.floor(ch / 2), Math.ceil(cw / 2), Math.ceil(ch / 2)], [Math.floor(cw / 2), Math.floor(ch / 2), Math.ceil(cw / 2), Math.ceil(ch / 2)], [Math.round(cw / 4), Math.round(ch / 4), Math.ceil(cw / 2), Math.ceil(ch / 2)]];
  for (const [x, y, rw, rh] of regions) {
    if (rw < 1 || rh < 1) continue;
    let id; try { id = ctx.getImageData(x, y, rw, rh); } catch (e) { continue; }
    let r; try { r = jsQR(id.data, rw, rh, { inversionAttempts: "attemptBoth" }); } catch (e) { r = null; }
    if (r && r.data && !seen.has(r.data)) { seen.add(r.data); found.push(r.data); if (found.length >= 6) break; }
  }
  return found; // 生文字列の配列（検証・提示は呼び出し側）
}

// --- Calendar helpers ---
// 予定の詳細テキスト（メモ＝note正規・旧memo互換／URL／チェックリスト）を外部カレンダー向けに整形。
function itemDetailsText(item) {
  const parts=[];
  const note=item.note||item.memo||"";
  if(note)parts.push(note);
  if(item.url)parts.push(item.url);
  if(Array.isArray(item.checklist)&&item.checklist.length)parts.push(item.checklist.map(c=>`${c.done?"☑":"☐"} ${c.text}`).join("\n"));
  return parts.join("\n");
}
// 終了日時：endTime があればそれ（開始以前なら翌日扱い）、無ければ従来どおり開始＋1時間。
function itemEndDate(item, st) {
  if(item.endTime){
    const [eh,emn]=item.endTime.split(":").map(Number);
    const en=new Date(st.getFullYear(),st.getMonth(),st.getDate(),eh,emn);
    if(en<=st)en.setDate(en.getDate()+1);
    return en;
  }
  return new Date(st.getTime()+3600000);
}
function gcalLink(item, memberName, memberEmoji) {
  const title = encodeURIComponent(`${item.emoji||""} ${item.title} [${memberEmoji}${memberName}]`);
  const [y,m,d]=item.dueDate.split("-").map(Number);
  let dates;
  if(item.time){
    const [h,mn]=item.time.split(":").map(Number);
    const fmt=(dt)=>`${dt.getFullYear()}${String(dt.getMonth()+1).padStart(2,"0")}${String(dt.getDate()).padStart(2,"0")}T${String(dt.getHours()).padStart(2,"0")}${String(dt.getMinutes()).padStart(2,"0")}00`;
    const st=new Date(y,m-1,d,h,mn);const en=itemEndDate(item,st);
    dates=`${fmt(st)}/${fmt(en)}`;
  }else{
    const s=`${y}${String(m).padStart(2,"0")}${String(d).padStart(2,"0")}`;
    // 複数日予定（endDate）は最終日の翌日までを終日範囲にする（Googleの終日は終了排他）。
    const last=(item.endDate&&item.endDate>item.dueDate)?item.endDate.split("-").map(Number):[y,m,d];
    const nd=new Date(last[0],last[1]-1,last[2]+1);
    const e=`${nd.getFullYear()}${String(nd.getMonth()+1).padStart(2,"0")}${String(nd.getDate()).padStart(2,"0")}`;
    dates=`${s}/${e}`;
  }
  let url=`https://calendar.google.com/calendar/render?action=TEMPLATE&text=${title}&dates=${dates}`;
  if(item.place)url+=`&location=${encodeURIComponent(item.place)}`;
  const details=itemDetailsText(item);
  if(details)url+=`&details=${encodeURIComponent(details)}`;
  {const rr=rruleFor(item);if(rr)url+=`&recur=${encodeURIComponent(rr)}`;}
  return url;
}

function generateIcal(items, members, meEmoji, meName, meSkinTone) {
  const nameOf=(sid)=>sid==="me"?(meName||"わたし"):(members.find(m=>m.id===sid)?.name||"");
  const emojiOf=(sid)=>sid==="me"?emojiWithTone(meEmoji,meSkinTone):memberEmojiOf(members.find(m=>m.id===sid));
  const now=new Date();
  const stamp=`${now.getFullYear()}${String(now.getMonth()+1).padStart(2,"0")}${String(now.getDate()).padStart(2,"0")}T${String(now.getHours()).padStart(2,"0")}${String(now.getMinutes()).padStart(2,"0")}00Z`;
  const esc=(s)=>String(s==null?"":s).replace(/\\/g,"\\\\").replace(/;/g,"\\;").replace(/,/g,"\\,").replace(/\r?\n/g,"\\n");
  const lines=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//LOALIFE//Family//JA","CALSCALE:GREGORIAN","METHOD:PUBLISH","X-WR-CALNAME:LOALIFE家族カレンダー"];
  items.filter(it=>it.dueDate&&!it.done).forEach(item=>{
    const [y,m,d]=item.dueDate.split("-").map(Number);
    lines.push("BEGIN:VEVENT");
    lines.push(`UID:loalife-${item.id}@loalife`);
    lines.push(`SUMMARY:${esc(`${item.emoji||""} ${item.title} [${emojiOf(item.space)}${nameOf(item.space)}]`)}`);
    lines.push(`DTSTAMP:${stamp}`);
    if(item.time){
      const [h,mn]=item.time.split(":").map(Number);
      const fmt=(dt)=>`${dt.getFullYear()}${String(dt.getMonth()+1).padStart(2,"0")}${String(dt.getDate()).padStart(2,"0")}T${String(dt.getHours()).padStart(2,"0")}${String(dt.getMinutes()).padStart(2,"0")}00`;
      const st=new Date(y,m-1,d,h,mn);const en=itemEndDate(item,st);
      lines.push(`DTSTART;TZID=Asia/Tokyo:${fmt(st)}`);
      lines.push(`DTEND;TZID=Asia/Tokyo:${fmt(en)}`);
    }else{
      const s=`${y}${String(m).padStart(2,"0")}${String(d).padStart(2,"0")}`;
      // 複数日予定（endDate）は最終日の翌日を DTEND にする（終日イベントは終了排他）。
      const last=(item.endDate&&item.endDate>item.dueDate)?item.endDate.split("-").map(Number):[y,m,d];
      const nd=new Date(last[0],last[1]-1,last[2]+1);
      const e=`${nd.getFullYear()}${String(nd.getMonth()+1).padStart(2,"0")}${String(nd.getDate()).padStart(2,"0")}`;
      lines.push(`DTSTART;VALUE=DATE:${s}`);lines.push(`DTEND;VALUE=DATE:${e}`);
    }
    {const rr=rruleFor(item);if(rr)lines.push(rr);}
    if(item.place)lines.push(`LOCATION:${esc(item.place)}`);
    const details=itemDetailsText(item);
    if(details)lines.push(`DESCRIPTION:${esc(details)}`);
    // リマインド設定がある場合のみ VALARM を付ける（無いアイテムには付けない）
    if(Array.isArray(item.reminders)&&item.reminders.length){
      item.reminders.forEach(mins=>{
        const trig=mins===0?"PT0M":(mins%1440===0?`-P${mins/1440}D`:`-PT${mins}M`);
        lines.push("BEGIN:VALARM");
        lines.push("ACTION:DISPLAY");
        lines.push(`TRIGGER:${trig}`);
        lines.push(`DESCRIPTION:${esc(item.title||"")}`);
        lines.push("END:VALARM");
      });
    }
    lines.push("END:VEVENT");
  });
  lines.push("END:VCALENDAR");
  return lines.join("\r\n");
}

function downloadIcal(content, filename="loalife-calendar.ics"){
  // Blob ダウンロードに統一。以前の iOS 用 form POST(target=_blank) は
  // PWAスタンドアロンで空白タブ（白い画面）になり進めなくなるため廃止。
  try{
    const blob=new Blob([content],{type:"text/calendar;charset=utf-8"});
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");
    a.href=url;a.download=filename;a.rel="noopener";
    document.body.appendChild(a);a.click();document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url),3000);
  }catch(e){
    // 最終フォールバック：同一タブでデータURLを開く（白い別タブは作らない）
    try{window.location.href="data:text/calendar;charset=utf-8,"+encodeURIComponent(content);}catch(_){}
  }
}

// テキストファイル（CSV等）のダウンロード。Excel が日本語を化けさせないよう BOM 付き。
function downloadTextFile(content, filename, mime="text/csv"){
  try{
    const blob=new Blob(["﻿"+content],{type:mime+";charset=utf-8"});
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");
    a.href=url;a.download=filename;a.rel="noopener";
    document.body.appendChild(a);a.click();document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url),3000);
  }catch(e){
    try{window.location.href="data:"+mime+";charset=utf-8,"+encodeURIComponent(content);}catch(_){}
  }
}
// DOMノードをPNG画像化して保存/共有（シート・カード・ポスターの「画像で保存」用）。
// ・.yl-noprint（ボタン等）は写さない ・常にライト配色で書き出す。
// ・iPhone等は共有シート（navigator.share）でアルバム保存・LINE送信できるように。
//   非対応環境（PC等）はファイルダウンロードにフォールバック。
// 返り値: "shared" | "download" | "aborted"
// 元canvasを指定サイズの枠に中央配置（SNSのストーリー等、決まった縦横比に整える用）。
function frameCanvas(src, W, H, bg){
  const c=document.createElement("canvas");c.width=W;c.height=H;
  const ctx=c.getContext("2d");ctx.fillStyle=bg||"#ffffff";ctx.fillRect(0,0,W,H);
  const pad=Math.round(W*0.045);
  const s=Math.min((W-pad*2)/src.width,(H-pad*2)/src.height);
  const w=Math.round(src.width*s),h=Math.round(src.height*s);
  ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality="high";
  ctx.drawImage(src,Math.round((W-w)/2),Math.round((H-h)/2),w,h);
  return c;
}
async function nodeToImageBlob(node, opts={}){
  const sheet=!!opts.sheet; // シート系は2カラムの用紙風にして縦長・余白を抑える
  const story=!!opts.story; // 迷子ポスターはSNS/ストーリー向けに幅広2カラム＋9:16の枠に整える
  let canvas=await html2canvas(node,{
    backgroundColor:"#ffffff",
    scale:2,
    useCORS:true,
    logging:false,
    windowWidth:sheet?800:(story?960:undefined), // 420px超で2カラムグリッドが効く
    ignoreElements:(el)=>el.classList&&el.classList.contains("yl-noprint"),
    onclone:(docu)=>{try{
      docu.documentElement.setAttribute("data-theme","light");
      if(sheet){const t=docu.querySelector(".yl-vetsum");if(t){t.classList.add("yl-shot");const m=t.closest(".yl-modal");if(m){m.style.maxWidth="none";m.style.width="auto";m.style.padding="0";}}}
      if(story){const t=docu.querySelector(".yl-lost-poster")||docu.querySelector(".yl-lost");if(t){t.classList.add("yl-lost-story");const m=t.closest(".yl-modal");if(m){m.style.maxWidth="none";m.style.width="auto";m.style.padding="0";}}}
      // object-fit:cover/contain の画像は html2canvas が表示枠へ引き伸ばしてしまうため、
      // 表示枠の比率に合わせて切り抜いた画像へ差し替える（緊急カード・迷子ポスター・
      // シート類など、画像書き出し全般の共通処理）。
      try{
        const liveBySrc={};document.querySelectorAll("img").forEach(li=>{if(li.src&&li.naturalWidth>0&&!liveBySrc[li.src])liveBySrc[li.src]=li;});
        docu.querySelectorAll("img").forEach(im=>{
          try{
            const live=liveBySrc[im.src];const srcImg=live||im;
            const nw=srcImg.naturalWidth||0,nh=srcImg.naturalHeight||0;if(!nw||!nh)return;
            let fit="";try{const cs=live?window.getComputedStyle(live):(docu.defaultView?docu.defaultView.getComputedStyle(im):null);fit=cs?cs.objectFit||"":"";}catch(e){}
            if(fit!=="cover"&&fit!=="contain")return;
            const bw=im.clientWidth||(live?live.clientWidth:0),bh=im.clientHeight||(live?live.clientHeight:0);if(!bw||!bh)return;
            const boxR=bw/bh,imgR=nw/nh;let sw=nw,sh=nh,sx=0,sy=0;
            if(fit==="cover"){if(imgR>boxR){sw=Math.max(1,Math.round(nh*boxR));sx=Math.round((nw-sw)/2);}else{sh=Math.max(1,Math.round(nw/boxR));sy=Math.round((nh-sh)/2);}}
            else{if(imgR>boxR){sh=Math.max(1,Math.round(nw/boxR));sy=Math.round((nh-sh)/2);}else{sw=Math.max(1,Math.round(nh*boxR));sx=Math.round((nw-sw)/2);}}
            if(sw===nw&&sh===nh)return;
            const cv=document.createElement("canvas");cv.width=sw;cv.height=sh;const cx=cv.getContext("2d");if(!cx)return;
            cx.drawImage(srcImg,sx,sy,sw,sh,0,0,sw,sh);im.src=cv.toDataURL("image/png");im.style.objectFit="fill";
          }catch(e){}
        });
      }catch(e){}
    }catch(e){}},
  });
  if(story)canvas=frameCanvas(canvas,1080,1920,"#ffffff"); // Instagramストーリー等の9:16に合わせる
  else if(opts.frame)canvas=frameCanvas(canvas,opts.frame[0],opts.frame[1],opts.frame[2]||"#ffffff"); // 汎用の縦横比フレーム（思い出カードのSNS縦長など）
  const blob=await new Promise((resolve)=>{if(canvas.toBlob)canvas.toBlob(resolve,"image/png");else{try{const durl=canvas.toDataURL("image/png");const bin=atob(durl.split(",")[1]);const arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);resolve(new Blob([arr],{type:"image/png"}));}catch(e){resolve(null);}}});
  if(!blob)throw new Error("no blob");
  return blob;
}
function downloadBlob(blob, filename){
  const url=URL.createObjectURL(blob);
  const a=document.createElement("a");
  a.href=url;a.download=filename;a.rel="noopener";
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url),3000);
}
async function saveNodeAsImage(node, filename, opts){
  const blob=await nodeToImageBlob(node,opts);
  // 共有シートが画像ファイルに対応していれば優先（iOS: 「画像を保存」でアルバムへ）。
  try{
    const file=new File([blob],filename,{type:"image/png"});
    if(navigator.canShare&&navigator.canShare({files:[file]})&&navigator.share){
      try{await navigator.share({files:[file]});return "shared";}
      catch(e){if(e&&e.name==="AbortError")return "aborted";/* 権限切れ等はDLへフォールバック */}
    }
  }catch(e){/* File未対応等はDLへ */}
  downloadBlob(blob,filename);
  return "download";
}
// CSV 1セルのエスケープ（カンマ・改行・引用符を含む場合は "" で囲む）。
const csvCell=(v)=>{const s=v==null?"":String(v);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;};

