// ── 天気の地点名の言語別解決 ──
// 地点名は登録時の言語の文字列で保存され固定されていたため、表示言語に追随しなかった。
// Open-Meteo Geocoding は language パラメータでその言語の地名を返すので、同じ地点を
// 各言語で引き直し、検索結果の id（geoId）で同一地点を突き合わせて名前表を作る。
// 座標の近さで同定する（旧データ移行用）。失敗時は null を返し、保存名の表示に留める。
const WX_NAME_LANGS=["ja","en","es","zh"];
const wxLabelFromRes=(res)=>res.name+(res.admin1&&res.admin1!==res.name?`・${res.admin1}`:"");
async function wxSearchNames(q,language,fetchImpl){
  const r=await fetchImpl(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=20&language=${language}&format=json`);
  const j=await r.json();
  return Array.isArray(j.results)?j.results:[];
}
// entry={name,lat,lon,geoId?,names?,custom?} → {geoId,names} | null
async function resolveWxNames(entry,fetchImpl){
  if(!entry||entry.custom||entry.lat==null||entry.lon==null)return null;
  if(entry.name==="現在地"||entry.name==="地点")return null; // センチネルは表示側で言語化する
  const f=fetchImpl||((u)=>fetch(u));
  const q=String(entry.name||"").split("・")[0].trim();
  if(!q)return null;
  let geoId=entry.geoId!=null?entry.geoId:null;
  const names={...(entry.names||{})};
  try{
    if(geoId==null){
      const list=await wxSearchNames(q,"ja",f);
      const hit=list.find(x=>Math.abs(x.latitude-entry.lat)<0.08&&Math.abs(x.longitude-entry.lon)<0.08);
      if(!hit)return null; // 近くに同名地点が無い＝手付けのラベル等。保存名のままにする
      geoId=hit.id;
      if(!names.ja)names.ja=wxLabelFromRes(hit);
    }
    for(const L of WX_NAME_LANGS){
      if(names[L])continue;
      const list=await wxSearchNames(q,L,f);
      const hit=list.find(x=>x.id===geoId);
      if(hit)names[L]=wxLabelFromRes(hit);
    }
  }catch(e){return null;}
  if(geoId==null||!WX_NAME_LANGS.some(L=>names[L]))return null;
  return {geoId,names};
}
function tr(lang,key,vars){
  let s=(MESSAGES[lang]&&MESSAGES[lang][key]);
  if(s==null&&lang!=="en")s=(MESSAGES.en&&MESSAGES.en[key]); // 未訳キーは英語にフォールバック（es 等の段階的追加用）
  if(s==null)s=(MESSAGES.ja&&MESSAGES.ja[key]);
  if(s==null)return key;
  if(vars)s=s.replace(/\{(\w+)\}/g,(mm,k)=>vars[k]!=null?String(vars[k]):mm);
  return s;
}
// 言語判定：navigator の言語を ja/en にマップ（該当なしは ja）。初回のみ利用。
function detectLang(){try{const ls=navigator.languages||[navigator.language||"ja"];for(const l of ls){const p=(l||"").toLowerCase();if(p.startsWith("en"))return "en";if(p.startsWith("ja"))return "ja";if(p.startsWith("es"))return "es";if(p.startsWith("zh"))return "zh";}}catch(e){}return "ja";}
// Intl.DateTimeFormat ベースの日付・曜日（絶対日付表示用の基盤。ja出力は既存表記に一致）。
function fmtDateLoc(isoStr,lang){if(!isoStr||typeof isoStr!=="string")return"";const[y,m,d]=isoStr.split("-").map(Number);if(!m||!d)return"";const dt=new Date(y&&y>1900?y:2001,m-1,d);try{return new Intl.DateTimeFormat(LOCALES[lang]||"ja-JP",lang==="ja"?{month:"long",day:"numeric"}:{month:"short",day:"numeric"}).format(dt);}catch(e){return`${m}/${d}`;}}
function fmtWeekdayLoc(isoStr,lang){if(!isoStr)return"";const[y,m,d]=isoStr.split("-").map(Number);if(!y||!m||!d)return"";try{return new Intl.DateTimeFormat(LOCALES[lang]||"ja-JP",{weekday:"short"}).format(new Date(y,m-1,d));}catch(e){return"";}}
// 思い出カード用：年つきの絶対日付（ja「2024年9月25日」/ 各言語）。
function fmtFullDateLoc(isoStr,lang){if(!isoStr||typeof isoStr!=="string")return"";const[y,m,d]=isoStr.split("-").map(Number);if(!y||!m||!d)return"";try{return new Intl.DateTimeFormat(LOCALES[lang]||"ja-JP",{year:"numeric",month:"long",day:"numeric"}).format(new Date(y,m-1,d));}catch(e){return`${y}/${m}/${d}`;}}

const HOURS=Array.from({length:24},(_,i)=>i);
const MINS=[0,5,10,15,20,25,30,35,40,45,50,55];
