const TYPE_ICON={work:"briefcase",event:"calendar",social:"users",habit:"repeat",health:"stethoscope",dream:"sparkles"};
const ENERGY_ICON={great:"smileplus",genki:"smile",normal:"meh",low:"frown",bad:"angry",mood_good:"smileplus",mood_ok:"meh",mood_fussy:"frown",mood_cry:"angry"};
const POOP_DIARY_ICON={good:"check",loose:"droplet",none:"ban",hard:"alert"};
function Icon({name,size=22,stroke=1.9,className}){const d=ICONS[name];if(!d)return null;return(<svg className={className} width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" dangerouslySetInnerHTML={{__html:d}}/>);}
// ===== お散歩マップ（Leaflet + OpenStreetMap。読み込めない環境ではSVGにフォールバック） =====
// Leaflet は index.html の head で defer 読み込みされるため、初回描画時点では未定義のことがある。少し待って拾う。
const useLeafletLib=()=>{
  const[lib,setLib]=useState(()=>typeof window!=="undefined"?(window.L||null):null);
  useEffect(()=>{
    if(lib)return;
    let n=0;
    const id=setInterval(()=>{ if(typeof window!=="undefined"&&window.L){setLib(window.L);clearInterval(id);} else if(++n>=24)clearInterval(id); },300);
    return()=>clearInterval(id);
  },[lib]);
  return lib;
};
// ルートのSVG描画（Leaflet不可時のフォールバック＆履歴サムネイル用）。スタート=緑、終端= endColor。
function RouteSvg({route,w=300,h=120,strokeWidth=3,dotR,endColor="#2F7FE0",className="yl-walkrec-map",style}){
  const{segs,first,last}=routeXY(route,w,h,Math.max(4,Math.round(w*0.04)));
  const r=dotR!=null?dotR:Math.max(2.5,strokeWidth+1.5);
  const total=segs.reduce((s,g)=>s+g.length,0);
  return(
    <svg className={className} viewBox={`0 0 ${w} ${h}`} style={style} role="img" aria-label="walk route">
      {segs.map((g,i)=>g.length>=2?<polyline key={i} points={g.map(p=>`${p.x},${p.y}`).join(" ")} fill="none" stroke="#E39A5C" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round"/>:null)}
      {first&&<circle cx={first.x} cy={first.y} r={r} fill="#2E9E5B" stroke="#fff" strokeWidth="1.5"/>}
      {last&&total>1&&<circle cx={last.x} cy={last.y} r={r} fill={endColor} stroke="#fff" strokeWidth="1.5"/>}
    </svg>
  );
}
// 本物の地図。live=記録中（現在地追従あり）、detail=履歴詳細（全体フィット）、mini=履歴リストのサムネイル（操作なし・全体フィット）。
function WalkMap({route,live=false,detail=false,mini=false,height=240}){
  const L=useLeafletLib();
  const boxRef=useRef(null);
  const mapRef=useRef(null);
  const layersRef=useRef([]);
  const followRef=useRef(true);
  const viewInitRef=useRef(false);
  const refitDoneRef=useRef(false);
  const[showLocate,setShowLocate]=useState(false);
  const segs=useMemo(()=>routeSegments(route),[route]);
  const allPts=useMemo(()=>segs.flat(),[segs]);
  const lastPt=allPts.length?allPts[allPts.length-1]:null;
  const searching=live&&allPts.length<2;
  // 地図の生成（Leaflet が来たら一度だけ）
  useEffect(()=>{
    if(!L||!boxRef.current||mapRef.current)return;
    let map=null;
    try{
      map=L.map(boxRef.current,mini?{zoomControl:false,attributionControl:true,dragging:false,scrollWheelZoom:false,doubleClickZoom:false,boxZoom:false,keyboard:false}:{zoomControl:true,attributionControl:true});
      if(mini&&map.attributionControl){try{map.attributionControl.setPrefix(false);}catch(e){}}
      L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap contributors"}).addTo(map);
      map.setView([35.68,139.69],6); // GPS未取得時の仮の視点（日本全体）
      map.on("dragstart",()=>{ if(followRef.current){followRef.current=false;setShowLocate(true);} });
      mapRef.current=map;
      const tm=setTimeout(()=>{try{map.invalidateSize();}catch(e){}},90);
      const tm2=setTimeout(()=>{try{map.invalidateSize();}catch(e){}},450);
      return()=>{clearTimeout(tm);clearTimeout(tm2);};
    }catch(e){ mapRef.current=null; }
  },[L]);
  // アンマウント時に地図を破棄
  useEffect(()=>()=>{ if(mapRef.current){try{mapRef.current.remove();}catch(e){} mapRef.current=null; layersRef.current=[]; } },[]);
  // ルートの同期（ポリライン＋マーカー＋視点）
  useEffect(()=>{
    const map=mapRef.current;
    if(!L||!map)return;
    layersRef.current.forEach(l=>{try{map.removeLayer(l);}catch(e){}});
    const layers=[];
    segs.forEach(seg=>{ if(seg.length>=2)layers.push(L.polyline(seg.map(p=>[p.lat,p.lng]),{color:"#E39A5C",weight:5,opacity:.95,lineCap:"round",lineJoin:"round"}).addTo(map)); });
    if(allPts.length)layers.push(L.circleMarker([allPts[0].lat,allPts[0].lng],{radius:7,color:"#fff",weight:2.5,fillColor:"#2E9E5B",fillOpacity:1}).addTo(map));
    if(allPts.length>1)layers.push(L.circleMarker([lastPt.lat,lastPt.lng],{radius:7,color:"#fff",weight:2.5,fillColor:live?"#2F7FE0":"#D9534F",fillOpacity:1}).addTo(map));
    layersRef.current=layers;
    try{
      if(detail||mini){
        const pad=mini?[8,8]:[26,26];
        if(allPts.length>=2)map.fitBounds(L.latLngBounds(allPts.map(p=>[p.lat,p.lng])),{padding:pad});
        else if(allPts.length===1)map.setView([allPts[0].lat,allPts[0].lng],17);
      }else if(live&&lastPt){
        if(!viewInitRef.current){ map.setView([lastPt.lat,lastPt.lng],17); viewInitRef.current=true; }
        else if(followRef.current)map.panTo([lastPt.lat,lastPt.lng],{animate:false});
      }
    }catch(e){}
    // detail/mini はモーダル・リストのレイアウト確定が地図生成に遅れることがあるため、
    // 一度だけ遅延してサイズ再計測＋全体フィットをやり直す（live の追従には触らない）。
    if((detail||mini)&&!refitDoneRef.current){
      refitDoneRef.current=true;
      const tm=setTimeout(()=>{
        const m=mapRef.current; if(!m)return;
        try{
          m.invalidateSize();
          const pad=mini?[8,8]:[26,26];
          if(allPts.length>=2)m.fitBounds(L.latLngBounds(allPts.map(p=>[p.lat,p.lng])),{padding:pad});
          else if(allPts.length===1)m.setView([allPts[0].lat,allPts[0].lng],17);
        }catch(e){}
      },380);
      return()=>clearTimeout(tm);
    }
  },[L,segs,allPts,lastPt,live,detail,mini]);
  const goLocate=()=>{ const map=mapRef.current; if(!map||!lastPt)return; followRef.current=true; setShowLocate(false); try{ map.setView([lastPt.lat,lastPt.lng],Math.max(map.getZoom()||0,16),{animate:false}); }catch(e){} };
  if(!L){
    return(
      <div className={"yl-walkmap-wrap"+(mini?" yl-walkmap-mini":"")} style={{height}}>
        <RouteSvg route={route} w={mini?Math.round(height*1.5):300} h={height} strokeWidth={3} endColor={live?"#2F7FE0":"#D9534F"} style={{height}}/>
        {searching&&<div className="yl-walkmap-searching">{tr(APP_LANG,"walk.gpsSearching")}</div>}
      </div>
    );
  }
  return(
    <div className={"yl-walkmap-wrap"+(mini?" yl-walkmap-mini":"")} style={{height}}>
      <div ref={boxRef} className="yl-walkmap" style={{height}}/>
      {searching&&<div className="yl-walkmap-searching">{tr(APP_LANG,"walk.gpsSearching")}</div>}
      {live&&showLocate&&lastPt&&<button type="button" className="yl-walkmap-locate" onClick={goLocate} aria-label={tr(APP_LANG,"walk.locate")}><Icon name="target" size={19}/></button>}
    </div>
  );
}
// うんちの硬さイラスト（塗り）。POOP_SHAPE のパスを tone 色で描画。
function PoopShape({n,size=30}){const d=POOP_SHAPE[n];if(!d)return null;const bm=bristolMeta(n);const col=(bm&&POOP_TONE_COLOR[bm.tone])||"#A9803F";return(<svg width={size} height={size} viewBox="0 0 24 24" fill={col} aria-hidden="true" dangerouslySetInnerHTML={{__html:d}}/>);}

// IME（日本語入力）に強いテキスト入力。変換中(composition)は親stateを更新せず、
// 変換確定時にまとめて反映する。背景の再描画で変換が消える不具合を防ぐ。
function IMEInput({value,onChange,onBlur,...rest}){
  const composing=useRef(false);
  const [local,setLocal]=useState(value||"");
  useEffect(()=>{ if(!composing.current&&value!==local)setLocal(value||""); },[value]); // eslint-disable-line
  // 変換中でも親へ即時反映する。表示値(local)は常にDOMの実値と一致させるので、
  // 親の再描画でinputのDOM値が書き換わることはなく、日本語変換は中断されない。
  // これによりiOS Safariでcompositionendが発火しない場合でも入力が確実に保存される。
  const push=(v)=>{setLocal(v);onChange(v);};
  return(<input {...rest} value={local}
    onCompositionStart={()=>{composing.current=true;}}
    onCompositionEnd={e=>{composing.current=false;push(e.target.value);}}
    onChange={e=>push(e.target.value)}
    onBlur={e=>{composing.current=false;push(e.target.value);if(onBlur)onBlur(e);}}/>);
}

function TimeInput({value,onChange}){
  const curH=value?Number(value.split(":")[0]):"";
  const rawM=value?Number(value.split(":")[1]):0;
  const curM=value?rawM:0;
  // 5分刻みでない分（例：07分）も選択肢に含め、表示・保存で勝手に丸めない。
  const minsShown=MINS.includes(rawM)?MINS:[...MINS,rawM].sort((a,b)=>a-b);
  const upd=(h,m)=>{if(h===""){onChange("");return;}const hh=String(h).padStart(2,"0"),mm=String(m).padStart(2,"0");onChange(hh+":"+mm);};
  return(<div className="yl-timepick"><select className="yl-tsel" value={curH} onChange={e=>upd(e.target.value===""?"":Number(e.target.value),curM)}><option value="">--</option>{HOURS.map(h=><option key={h} value={h}>{String(h).padStart(2,"0")}</option>)}</select><span className="yl-tcolon">:</span><select className="yl-tsel" value={curM} onChange={e=>{if(curH==="")return;upd(curH,Number(e.target.value));}}>{minsShown.map(m=><option key={m} value={m}>{String(m).padStart(2,"0")}</option>)}</select></div>);
}
// 終了時刻の検証：終了だけ入っている／開始より前、は保存せず理由を返す（"start"|"order"|null）。
const endTimeBad=(time,end)=>{if(end&&!time)return"start";if(time&&end&&end<=time)return"order";return null;};

// 誕生日・記念日の入力：月・日は必須、年（西暦）は任意。毎年くりかえす前提で、
// 年が空のときは内部的に "0000-MM-DD" で保存し、年齢/周年は表示しない。
const BMONTHS=Array.from({length:12},(_,i)=>i+1);
const dimOf=(mm,yy)=>{if(!mm)return 31;const yr=/^\d{4}$/.test(yy||"")?Number(yy):2000;return new Date(yr,Number(mm),0).getDate();}; // 年が分かればその年で（うるう年対応）、不明ならうるう年2000で安全側に算出
function BdayInput({value,onChange}){
  const[y,setY]=useState("");const[m,setM]=useState("");const[d,setD]=useState("");
  // 外から値が渡された時に同期。年は実在年のときだけ反映し、"0000"では上書きしない（入力中の桁を消さないため）。
  useEffect(()=>{const p=(value||"").split("-");if(p.length===3){setM(String(Number(p[1])));setD(String(Number(p[2])));if(p[0]!=="0000")setY(p[0]);}else{setM("");setD("");setY("");}},[value]);
  const emit=(yy,mm,dd)=>{if(!mm||!dd){onChange("");return;}const yr=/^\d{4}$/.test(yy)?yy:"0000";onChange(`${yr}-${String(Number(mm)).padStart(2,"0")}-${String(Number(dd)).padStart(2,"0")}`);};
  const onMonth=e=>{const nm=e.target.value;let nd=d;if(nm&&d&&Number(d)>dimOf(nm,y))nd=String(dimOf(nm,y));setM(nm);setD(nd);emit(y,nm,nd);};
  const onDay=e=>{const nd=e.target.value;setD(nd);emit(y,m,nd);};
  const onYear=e=>{const v=e.target.value.replace(/[^0-9]/g,"").slice(0,4);setY(v);let nd=d;if(m&&d&&Number(d)>dimOf(m,v))nd=String(dimOf(m,v));setD(nd);emit(v,m,nd);};
  const monthSel=(<select key="m" className="yl-bsel" value={m} onChange={onMonth}><option value="">{tr(APP_LANG,"bday.month")}</option>{BMONTHS.map(mm=><option key={mm} value={mm}>{mm}{tr(APP_LANG,"bday.monthSuffix")}</option>)}</select>);
  const daySel=(<select key="d" className="yl-bsel" value={d} onChange={onDay}><option value="">{tr(APP_LANG,"bday.day")}</option>{Array.from({length:dimOf(m,y)},(_,i)=>i+1).map(dd=><option key={dd} value={dd}>{dd}{tr(APP_LANG,"bday.daySuffix")}</option>)}</select>);
  const yearIn=(<input key="y" className="yl-byear" type="text" inputMode="numeric" maxLength={4} placeholder={tr(APP_LANG,"bday.yearOpt")} value={y} onChange={onYear}/>);
  // 並びは言語の慣れた順序にする（表示のみ。値の保持・保存は従来どおり）：ja/zh=年・月・日、en=月・日・年、es=日・月・年
  const fields=(APP_LANG==="en")?[monthSel,daySel,yearIn]:(APP_LANG==="es")?[daySel,monthSel,yearIn]:[yearIn,monthSel,daySel];
  return(<span className="yl-bdaypick">{fields}</span>);
}

// ───────── コーチマーク（スポットライト型ガイド） ─────────
// 対象要素の実測位置(getBoundingClientRect)にスポットライトと吹き出しを重ねる。
// 座標はベタ書きせず、要素をセレクタで探して毎フレーム追従（リサイズ・スクロールにも対応）。
const TOUR_STEPS=[
  {k:"headseg",sel:'[data-tour="headseg"]'},
  {k:"fab",sel:'[data-tour="fab"]'},
  {k:"cal",sel:'[data-tour="nav-cal"]'},
  {k:"home",sel:'[data-tour="nav-home"]'},
];
// 画面ごとの初回1ポイント案内（B）。キー＝画面（coach.<key>.title/body）、value＝{sel}
const COACH_HINTS={
  cal:{sel:".yl-cal-grid"},
  record:{sel:'[data-tour="fab"]'},
  manage:{sel:".yl-chore, .yl-routine, .yl-list"},
};
// 永続フラグ（UI設定なのでローカル保存。ツアーAと画面案内Bは別キーで管理）。
const tourIsDone=()=>{try{return localStorage.getItem("loalife-tour-v1")==="1";}catch(e){return true;}};
const markTourDone=()=>{try{localStorage.setItem("loalife-tour-v1","1");}catch(e){}};
const coachIsSeen=(k)=>{try{return !!(JSON.parse(localStorage.getItem("loalife-coach-v1")||"{}")[k]);}catch(e){return true;}};
const markCoachSeen=(k)=>{try{const o=JSON.parse(localStorage.getItem("loalife-coach-v1")||"{}");o[k]=1;localStorage.setItem("loalife-coach-v1",JSON.stringify(o));}catch(e){}};
const resetGuides=()=>{try{localStorage.removeItem("loalife-tour-v1");localStorage.removeItem("loalife-coach-v1");}catch(e){}};
function CoachMark({sel,title,body,step,total,nextLabel,onNext,onSkip,single}){
  const[rect,setRect]=useState(null);
  const foundRef=useRef(false);
  useEffect(()=>{
    const measure=()=>{const el=document.querySelector(sel);if(el){const r=el.getBoundingClientRect();if(r.width||r.height){foundRef.current=true;setRect({top:r.top,left:r.left,width:r.width,height:r.height});return;}}setRect(null);};
    measure();const iv=setInterval(measure,150);
    window.addEventListener("resize",measure);window.addEventListener("scroll",measure,true);
    return()=>{clearInterval(iv);window.removeEventListener("resize",measure);window.removeEventListener("scroll",measure,true);};
  },[sel]);
  // 対象要素が画面に無い案内は、一定時間で自動的に閉じる（閉じないと他の画面の案内まで出なくなる）。
  useEffect(()=>{const id=setTimeout(()=>{if(!foundRef.current&&onNext)onNext();},1500);return()=>clearTimeout(id);},[sel]);
  if(!rect)return null; // 対象が見つかるまで待つ（見つかり次第スポットライト表示）
  const pad=8;const vh=typeof window!=="undefined"?window.innerHeight:800;
  const hole={top:rect.top-pad,left:rect.left-pad,w:rect.width+pad*2,h:rect.height+pad*2};
  const placeBelow=(hole.top+hole.h+16)<(vh-190);
  const tipStyle=placeBelow?{top:hole.top+hole.h+14}:{bottom:(vh-hole.top)+14};
  return(<div className="yl-coach">
    <div className="yl-coach-hole" style={{top:hole.top,left:hole.left,width:hole.w,height:hole.h}}/>
    <div className="yl-coach-tip" style={tipStyle}>
      {total?<span className="yl-coach-step">{step} / {total}</span>:null}
      <h4 className="yl-coach-title">{title}</h4>
      <p className="yl-coach-body">{body}</p>
      <div className="yl-coach-btns">
        {!single&&<button className="yl-coach-skip" onClick={onSkip}>{tr(APP_LANG,"tour.skip")}</button>}
        <button className="yl-coach-next" onClick={onNext}>{nextLabel}</button>
      </div>
    </div>
  </div>);
}

// 体重・身長の推移グラフ（軽量SVG折れ線）。points=[{date,value}]（古い→新しい順）
// 2点以上でのみ折れ線を描く（1点以下は呼び出し側で空状態メッセージ）。
function MiniChart({points,unit,color,label,band,bandPts,bandLabel}){
  if(!points||points.length<2)return null;
  // 描画エリアを分離：左＝Y軸ラベルの余白、下＝X軸ラベルの余白。折れ線はその内側だけに描く。
  const W=300,H=120,padL=40,padR=14,padTop=14,padBot=22;
  const plotB=H-padBot; // プロット領域の下端（X軸ラベルはこれより下に描く）
  const vals=points.map(p=>p.value);
  const ptMin=Math.min(...vals),ptMax=Math.max(...vals);
  // 帯（目標範囲・成長曲線の目安）がある場合は帯もスケールに含める。
  const extra=[];if(band){extra.push(band.lo,band.hi);}if(bandPts)bandPts.forEach(b=>{if(b){extra.push(b.lo,b.hi);}});
  const dataMin=Math.min(ptMin,...extra),dataMax=Math.max(ptMax,...extra);
  // Y軸に余白：最小レンジと上下パディングを確保し、0.1kg差が画面端から端まで振れないように。
  let min=dataMin,max=dataMax,span=max-min;
  const floor=Math.max((Math.abs(max)||1)*0.12,unit==="cm"?2:(unit==="kg"?1:0.4));
  if(span<floor){const c=(min+max)/2;min=c-floor/2;max=c+floor/2;span=floor;}
  const padv=span*0.2;min-=padv;max+=padv;span=max-min;
  const n=points.length;
  const xAt=(i)=>padL+(i*(W-padL-padR))/(n-1);
  const yAt=(v)=>padTop+(1-(v-min)/span)*(plotB-padTop);
  const fmtV=(v)=>Number.isInteger(v)?v:v.toFixed(1);
  const latest=points[n-1],first=points[0];
  return(
    <div className="yl-chart-wrap">
      <div className="yl-chart-head"><span className="yl-chart-label">{label}</span><span className="yl-chart-latest" style={{color}}>{latest.value}{unit}</span></div>
      <svg className="yl-chart" viewBox={`0 0 ${W} ${H}`}>
        {/* プロット領域の枠（下端の基準線） */}
        <line x1={padL} y1={plotB} x2={W-padR} y2={plotB} stroke="#E7E1D8" strokeWidth="1"/>
        {/* 目標範囲の帯（一定範囲）＋目標値の破線 */}
        {band&&<rect x={padL} y={yAt(band.hi).toFixed(1)} width={W-padL-padR} height={Math.max(0,yAt(band.lo)-yAt(band.hi)).toFixed(1)} fill={color} opacity="0.10"/>}
        {band&&band.target!=null&&<line x1={padL} y1={yAt(band.target).toFixed(1)} x2={W-padR} y2={yAt(band.target).toFixed(1)} stroke={color} strokeWidth="1" strokeDasharray="4 3" opacity="0.55"/>}
        {/* 成長曲線の目安帯（点ごとに範囲が変わる） */}
        {bandPts&&bandPts.some(b=>b)&&(()=>{const idxs=points.map((p,i)=>i).filter(i=>bandPts[i]);const up=idxs.map(i=>`${xAt(i).toFixed(1)},${yAt(bandPts[i].hi).toFixed(1)}`);const dn=idxs.slice().reverse().map(i=>`${xAt(i).toFixed(1)},${yAt(bandPts[i].lo).toFixed(1)}`);return<polygon points={[...up,...dn].join(" ")} fill={color} opacity="0.10"/>;})()}
        <polyline points={points.map((p,i)=>`${xAt(i).toFixed(1)},${yAt(p.value).toFixed(1)}`).join(" ")} fill="none" stroke={color} strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round"/>
        {points.map((p,i)=><circle key={i} cx={xAt(i).toFixed(1)} cy={yAt(p.value).toFixed(1)} r="3" fill={color}/>)}
        {/* Y軸：左の余白に上＝データ最大・下＝データ最小（右寄せ） */}
        <text x={padL-6} y={padTop+4} textAnchor="end" className="yl-chart-ax">{fmtV(ptMax)}{unit}</text>
        <text x={padL-6} y={plotB} textAnchor="end" className="yl-chart-ax">{fmtV(ptMin)}{unit}</text>
        {/* X軸：下の余白に起点（左寄せ）と最新（右寄せ） */}
        {n>1&&<text x={padL} y={H-6} textAnchor="start" className="yl-chart-ax">{fmtDate(first.date)}</text>}
        <text x={W-padR} y={H-6} textAnchor="end" className="yl-chart-ax">{fmtDate(latest.date)}</text>
      </svg>
      {bandLabel&&<p className="yl-chart-bandnote">{bandLabel}</p>}
    </div>
  );
}

// 重ねグラフ（#9/#5）：日付軸を共有し、複数系列を重ねる。左軸=主系列（体重など）、
// 右軸=副系列（身長・カスタム項目など単位の違うもの）。band は左軸の目標範囲。
// series=[{points:[{date,value}],color,label,unit,axis:"l"|"r"}]
function MultiChart({series,band,bandLabel}){
  const all=(series||[]).filter(s=>s.points&&s.points.length>=2);
  if(!all.length)return null;
  const W=300,H=120,padL=40,padR=40,padTop=14,padBot=22;
  const plotB=H-padBot;
  const dates=all.flatMap(s=>s.points.map(p=>p.date)).sort();
  const t0=new Date(dates[0]+"T00:00:00").getTime();let t1=new Date(dates[dates.length-1]+"T00:00:00").getTime();if(!(t1>t0))t1=t0+86400000;
  const xAt=(date)=>padL+((new Date(date+"T00:00:00").getTime()-t0)/(t1-t0))*(W-padL-padR);
  const scaleFor=(axis)=>{
    const vs=all.filter(s=>(s.axis||"l")===axis).flatMap(s=>s.points.map(p=>p.value));
    if(axis==="l"&&band)vs.push(band.lo,band.hi);
    if(!vs.length)return null;
    const dmin=Math.min(...vs),dmax=Math.max(...vs);
    let min=dmin,max=dmax,span=max-min;
    const floor=Math.max((Math.abs(max)||1)*0.12,0.4);
    if(span<floor){const c=(min+max)/2;min=c-floor/2;max=c+floor/2;span=floor;}
    const padv=span*0.2;min-=padv;max+=padv;
    return{min,max,span:max-min,dmin,dmax};
  };
  const sl=scaleFor("l"),sr=scaleFor("r");
  const yAt=(v,sc)=>padTop+(1-(v-sc.min)/sc.span)*(plotB-padTop);
  const fmtV=(v)=>Number.isInteger(v)?v:Math.round(v*10)/10;
  const primary=all.find(s=>(s.axis||"l")==="l")||all[0];
  return(
    <div className="yl-chart-wrap">
      <div className="yl-chart-head yl-chart-legend">{all.map((s,i)=>{const lp=s.points[s.points.length-1];return(<span key={i} className="yl-chart-legitem"><span className="yl-chart-dot" style={{background:s.color}}/>{s.label} <b style={{color:s.color}}>{lp.value}{s.unit}</b></span>);})}</div>
      <svg className="yl-chart" viewBox={`0 0 ${W} ${H}`}>
        <line x1={padL} y1={plotB} x2={W-padR} y2={plotB} stroke="#E7E1D8" strokeWidth="1"/>
        {band&&sl&&<rect x={padL} y={yAt(band.hi,sl).toFixed(1)} width={W-padL-padR} height={Math.max(0,yAt(band.lo,sl)-yAt(band.hi,sl)).toFixed(1)} fill={primary.color} opacity="0.10"/>}
        {band&&sl&&band.target!=null&&<line x1={padL} y1={yAt(band.target,sl).toFixed(1)} x2={W-padR} y2={yAt(band.target,sl).toFixed(1)} stroke={primary.color} strokeWidth="1" strokeDasharray="4 3" opacity="0.55"/>}
        {all.map((s,i)=>{const sc=(s.axis||"l")==="r"?sr:sl;if(!sc)return null;return(<g key={i}><polyline points={s.points.map(p=>`${xAt(p.date).toFixed(1)},${yAt(p.value,sc).toFixed(1)}`).join(" ")} fill="none" stroke={s.color} strokeWidth="2.5" strokeLinejoin="round" strokeLinecap="round"/>{s.points.map((p,j)=><circle key={j} cx={xAt(p.date).toFixed(1)} cy={yAt(p.value,sc).toFixed(1)} r="3" fill={s.color}/>)}</g>);})}
        {sl&&<text x={padL-6} y={padTop+4} textAnchor="end" className="yl-chart-ax">{fmtV(sl.dmax)}{primary.unit}</text>}
        {sl&&<text x={padL-6} y={plotB} textAnchor="end" className="yl-chart-ax">{fmtV(sl.dmin)}{primary.unit}</text>}
        {sr&&<text x={W-padR+6} y={padTop+4} textAnchor="start" className="yl-chart-ax">{fmtV(sr.dmax)}{(all.find(s=>s.axis==="r")||{}).unit||""}</text>}
        {sr&&<text x={W-padR+6} y={plotB} textAnchor="start" className="yl-chart-ax">{fmtV(sr.dmin)}{(all.find(s=>s.axis==="r")||{}).unit||""}</text>}
        <text x={padL} y={H-6} textAnchor="start" className="yl-chart-ax">{fmtDate(dates[0])}</text>
        <text x={W-padR} y={H-6} textAnchor="end" className="yl-chart-ax">{fmtDate(dates[dates.length-1])}</text>
      </svg>
      {bandLabel&&<p className="yl-chart-bandnote">{bandLabel}</p>}
    </div>
  );
}

// Visibility toggle component
function VisibilityToggle({value, onChange}) {
  const isHousehold = visOf(value) === "household";
  return (
    <button
      className={"yl-vis-toggle" + (isHousehold ? " household" : " private")}
      onClick={() => onChange(isHousehold ? "private" : "household")}
      title={isHousehold ? "家族に見せています" : "自分だけに表示"}
    >
      {isHousehold ? "👨‍👩‍👧 家族に見せる" : "🔒 自分のみ"}
    </button>
  );
}

// 大項目（セクション）並び替え用ラッパー。ドラッグは見出しのハンドル(⠿)のみ。
function SortableSection({id,children}){
  const {attributes,listeners,setNodeRef,transform,transition,isDragging}=useSortable({id});
  const style={transform:CSS.Transform.toString(transform),transition,position:"relative",...(isDragging?{opacity:.7,zIndex:30,boxShadow:"0 12px 28px rgba(120,80,160,.28)",borderRadius:18}:{})};
  return(
    <div ref={setNodeRef} style={style} className="yl-sec-wrap">
      <button className="yl-sec-handle" {...attributes} {...listeners} aria-label={tr(APP_LANG,"a11y.reorder")} title={tr(APP_LANG,"a11y.reorderDrag")}>⠿</button>
      {children}
    </div>
  );
}
// 並び替え用カード（長押し/ドラッグでD&D）。ドラッグ中は拡大・影・半透明。
function SortableCard({id,className,children}){
  const {attributes,listeners,setNodeRef,transform,transition,isDragging}=useSortable({id});
  const base=CSS.Transform.toString(transform);
  const style={transform:isDragging&&base?`${base} scale(1.03)`:base,transition,touchAction:"manipulation",...(isDragging?{opacity:.65,boxShadow:"0 12px 28px rgba(120,80,160,.28)",zIndex:20,position:"relative"}:{})};
  return <li ref={setNodeRef} style={style} className={className} {...attributes} {...listeners}>{children}</li>;
}

