  // 名刺の専用画面を開く（メンバー詳細の「名刺」入口から）。
  const openCardScreen=(m)=>{if(!m)return;
    // 捜索中でないメンバーは、前回の事件情報の下書きを保存データからも消してから開く
    // （旧ウィザードの開封時クリアと同じ保証を、名刺画面へ移したもの）。
    if(!m.cardLost&&!m.lostPosterPublic){const cleared=lostIncidentCleared(m.lostInfo);if(cleared)persist(members.map(x=>x.id===m.id?{...x,lostInfo:cleared}:x),items);}
    fillCardEdit(m);setCardScreenId(m.id);};
  const requestCloseCardScreen=()=>{if(cardSnap&&cardFormSnap()!==cardSnap){setConfirmDiscardCard(true);}else{setCardScreenId(null);}};
  const doDiscardCard=()=>{setConfirmDiscardCard(false);setCardScreenId(null);};
  // 名刺画面の保存：名刺まわりの項目だけをメンバーへ反映し、公開中なら公開ドキュメントも更新する。
  const saveCardEdit=(id)=>{
    const prevM=members.find(m=>m.id===id);if(!prevM)return;
    const upd=cardMemberFromForm(prevM);
    const next=members.map(m=>m.id===id?upd:m);
    persist(next,items);
    clearSampleMode();
    // 名刺専用写真を差し替え・解除した場合、専用コピー（cp 接頭辞）の実体を片付ける（アバターや記録の写真は消さない）。
    if(prevM.cardPhoto&&prevM.cardPhoto.indexOf("cp")===0&&upd.cardPhoto!==prevM.cardPhoto){try{photoStorage.delete(`photo:${prevM.cardPhoto}`);}catch(e){}setPhotos(p=>{if(!p[prevM.cardPhoto])return p;const n={...p};delete n[prevM.cardPhoto];return n;});}
    // 追加写真から外した専用コピーも同じく片付ける。
    if(Array.isArray(prevM.cardPhotos))prevM.cardPhotos.forEach(pid=>{if(pid&&pid.indexOf("cp")===0&&upd.cardPhotos.indexOf(pid)<0){try{photoStorage.delete(`photo:${pid}`);}catch(e){}setPhotos(p=>{if(!p[pid])return p;const n={...p};delete n[pid];return n;});}});
    saveMemberToFs(upd).catch(()=>{});
    if(upd.cardId&&upd.cardPublic&&fireUser)publishCard(upd).catch(()=>{});
    setCardScreenId(null);
  };
  // ホームの帯から迷子モードを切る。名刺画面の保存と同じ経路（メンバー更新→世帯同期→公開中なら公開ドキュメント再発行）。
  const turnOffLostMode=(m)=>{
    if(!m||!m.cardLost)return;
    const upd={...m,cardLost:false};
    const next=members.map(x=>x.id===m.id?upd:x);
    persist(next,items);
    saveMemberToFs(upd).catch(()=>{});
    if(upd.cardId&&upd.cardPublic&&fireUser)publishCard(upd).catch(()=>{});
    showFlash(t("toast.saved"));
  };
  // 名刺のQRコードを画像（PNG）として保存する。印刷して渡せるよう、白背景＋子の名前入りで書き出す。
  const saveCardQrPng=async(cm)=>{
    if(!cm||!cm.cardId||cardQrBusy)return;
    const enc=qrEncodeText(petCardLink(cm.cardId));
    if(!enc){showFlash(t("card.publishFail"));return;}
    setCardQrBusy(true);
    try{
      const q=4,modPx=12,W=(enc.size+q*2)*modPx,H=W+64;
      const cv=document.createElement("canvas");cv.width=W;cv.height=H;
      const ctx=cv.getContext("2d");
      ctx.fillStyle="#FFFFFF";ctx.fillRect(0,0,W,H);
      ctx.fillStyle="#26221E";
      for(let y=0;y<enc.size;y++)for(let x=0;x<enc.size;x++)if(enc.mod[y][x])ctx.fillRect((x+q)*modPx,(y+q)*modPx,modPx,modPx);
      ctx.textAlign="center";ctx.font="700 30px sans-serif";
      ctx.fillText((cm.name||"")+" 🐾 LOALIFE",W/2,W+42);
      const a=document.createElement("a");a.download="loalife-card-qr.png";a.href=cv.toDataURL("image/png");a.click();
    }catch(e){showFlash(t("card.publishFail"));}
    setCardQrBusy(false);
  };
  // 指定メンバーのプロフィール編集を開く（追加直後の案内から利用）。編集state群を対象メンバーで初期化。
  const startMemberEdit=(m)=>{if(!m)return;setTab(m.id);setMemberSel(m.id);setPersonSeg("manage");setEditName(m.name);setEditNickname(m.nickname||"");setEditBirthday(m.birthday||"");setEditGotcha(m.gotchaDay||"");setEditGroup(m.group||"");setEditMicrochip(m.microchip||"");setEditBreed(m.breed||"");setEditCoat(m.coat||"");setEditNeuter(m.neuter||"");setEditMemorial(m.memorial||"");setEditAvatar(m.avatar||"");setEditVisibility(visOf(m));setEditPersonType(m.personType||"child");setEditGender(m.gender||"");setEditBlood(m.blood||"");setEditEmoji(m.emoji||"");setEditSkinTone(m.skinTone||"");setEditKindText(m.kindText||"");fillCardEdit(m);setProfileOpen(true);setEditingId(m.id);};
  useEffect(()=>{if(inputSheet!=="schedule"){setDraftPhoto(null);setSelfCare(false);}},[inputSheet]); // ケア追加フォームを閉じたら未保存の写真・自分ケアフラグをクリア

  // ─── オーナー権限（破壊的な操作の可否） ─────────────────────────
  // メンバーの削除や公開名刺の操作など、取り返しのつかない操作をできる人：
  // 世帯オーナーは全部可、メンバーを作った本人は自分のメンバー分だけ可、それ以外は不可。
  // 単独利用（世帯に入っていない）場合は従来どおり全部可（制限は共有文脈でのみ効く）。
  // Firestore ルール側でも同じ条件を強制している（UIは出し分け、ルールが最後の砦）。
  const fsMemberOwnerUid=(m)=>{
    if(!m)return null;
    if(m.ownerUid)return m.ownerUid;
    const meta=fsIdsRef.current&&fsIdsRef.current.memberMeta?fsIdsRef.current.memberMeta.get(m.id):null;
    return meta&&meta.ownerUid?meta.ownerUid:null;
  };
  const canManageMember=(m)=>{
    if(!m||m.id==="me")return false;
    if(!household||!fireUser)return true;
    if(household.ownerUid&&fireUser.uid===household.ownerUid)return true;
    const ou=fsMemberOwnerUid(m);
    if(ou)return ou===fireUser.uid;
    // サーバー未登録のメンバーは、この端末で作ってまだ送っていないものだけが見えている
    const known=!!(fsIdsRef.current&&fsIdsRef.current.memberIds&&fsIdsRef.current.memberIds.has(m.id));
    return !known;
  };

  const removeMember=(id)=>{
    if(id==="me")return; // 「わたし」は削除対象外（アプリの前提が崩れるため）
    const m=members.find(x=>x.id===id);
    if(m&&!canManageMember(m))return; // オーナー権限のないメンバーの削除は受け付けない（ルール側でも拒否される）
    const removedItems=items.filter(x=>x.space===id);
    // 写真も一緒に消す：アバター・ポスター写真・削除される記録の写真（IndexedDB の photo: キー）
    const pids=new Set();
    if(m){if(m.avatar)pids.add(m.avatar);if(m.cardPhoto)pids.add(m.cardPhoto);(m.posterPhotos||[]).forEach(p=>pids.add(p));}
    removedItems.forEach(it=>photoIdsOf(it).forEach(p=>pids.add(p)));
    pids.forEach(pid=>{try{photoStorage.delete(`photo:${pid}`);}catch(e){}});
    if(pids.size)setPhotos(p=>{const n={...p};pids.forEach(pid=>delete n[pid]);return n;});
    // そのメンバーのお散歩が進行中なら破棄する（GPS監視も止める）
    if(walk&&walk.space===id)cancelWalk();
    persist(members.filter(x=>x.id!==id),items.filter(x=>x.space!==id));
    clearSampleMode();
    // Firestore 側の削除は失敗してもローカル削除は完了させる。失敗は静かにトーストで伝える。
    deleteMemberFromFs(id).then(ok=>{if(!ok)showFlash(t("toast.memberFsDeleteFail"));}).catch(()=>{});
    // 公開名刺を出していたメンバーは、公開ドキュメントも一緒に消す（リンク先が残らないように）。
    if(m&&m.cardId&&fireUser&&fbDb){try{deleteDoc(doc(fbDb,"publicCards",m.cardId)).catch(()=>{});}catch(e){}}
    // サマリー共有リンクを発行していたメンバーは、その公開ドキュメントも一緒に消す（医療情報のリンク先を残さない）。
    if(m&&Array.isArray(m.summaryLinks)&&fireUser&&fbDb){m.summaryLinks.forEach(l=>{try{deleteDoc(doc(fbDb,"publicSummaries",l.id)).catch(()=>{});}catch(e){}});}
    // 迷子ポスターを公開していたメンバーは、公開ページも一緒に消す（連絡先のリンク先を残さない）。
    if(m&&m.lostPosterId&&fireUser&&fbDb){try{deleteDoc(doc(fbDb,"publicPosters",m.lostPosterId)).catch(()=>{});}catch(e){}}
    setTab("me");setMemberSel("me");setConfirmDel(null);setEditingId(null);setProfileOpen(false);
    if(m)showFlash(t("toast.memberDeleted",{name:m.name}));
  };

  const saveRename=(id)=>{
    const name=editName.trim();if(!name)return;
    // 名刺まわりの項目（性格・SNS・名刺写真・テーマ等）は名刺画面の担当なので、ここでは触らず既存値を保持する。
    const next=members.map(m=>m.id===id?{...m,name,nickname:editNickname.trim()||"",birthday:editBirthday,gotchaDay:editGotcha||"",group:editGroup.trim()||"",microchip:editMicrochip.trim()||"",breed:editBreed.trim()||"",coat:editCoat.trim()||"",neuter:editNeuter||"",memorial:(m.kind==="pet"?(editMemorial||""):""),avatar:editAvatar||"",emoji:editEmoji||m.emoji,skinTone:(m.kind==="person"&&isToneableEmoji(editEmoji))?editSkinTone:"",visibility:editVisibility,...(m.kind==="person"?{personType:editPersonType,gender:editGender||"",blood:editBlood||""}:(m.kind==="pet"?{gender:editGender||"",kindText:editKindText.trim()}:{}))}:m);
    persist(next,items);
    clearSampleMode();
    const updated=next.find(m=>m.id===id);
    if(updated)saveMemberToFs(updated).catch(()=>{});
    // 写真共有の後始末：「自分のみ」に変えたら共有写真をすべて取り下げ、アバターを差し替えたら
    // 旧アバターがどこからも参照されていなければ取り下げる（共有の境界と実態を一致させる）。
    const prevM=members.find(m=>m.id===id);
    if(prevM&&updated&&household&&fireUser){
      if(visOf(updated)!=="household")deleteAllPhotosFromFs(id).catch(()=>{});
      else if(prevM.avatar&&prevM.avatar!==updated.avatar)cleanupPhotoIfOrphan(id,prevM.avatar,{memberOverride:updated}).catch(()=>{});
    }
    // 名刺を公開中のメンバーは、プロフィール保存に合わせて公開内容も更新する（失敗しても保存自体は完了扱い）。
    if(updated&&updated.cardId&&updated.cardPublic&&fireUser)publishCard(updated).catch(()=>{});
    setEditingId(null);
  };
  // 写真アイコンを選ぶ（編集フォーム内）。IDBに保存して editAvatar にセット
  const pickAvatar=async(e)=>{
    const file=e.target.files&&e.target.files[0];e.target.value="";if(!file)return;
    if(file.size>20*1024*1024){showFlash(t("toast.fileTooBig"));return;}
    try{const dataUrl=await downscaleImage(file,400,0.8);const pid="av"+Date.now();const ok=await photoStorage.set(`photo:${pid}`,dataUrl);if(!ok){showFlash(t("toast.storageFull"));return;}setPhotos(p=>({...p,[pid]:dataUrl}));setEditAvatar(pid);}
    catch(er){showFlash(t("toast.imgFail"));}
  };
  // 写真アイコンを選ぶ（追加フォーム用の共通処理）。IDBに保存し、set で photo id を反映。
  const pickAvatarInto=async(e,set)=>{
    const file=e.target.files&&e.target.files[0];e.target.value="";if(!file)return;
    if(file.size>20*1024*1024){showFlash(t("toast.fileTooBig"));return;}
    try{const dataUrl=await downscaleImage(file,400,0.8);const pid="av"+Date.now();const ok=await photoStorage.set(`photo:${pid}`,dataUrl);if(!ok){showFlash(t("toast.storageFull"));return;}setPhotos(p=>({...p,[pid]:dataUrl}));set(pid);}
    catch(er){showFlash(t("toast.imgFail"));}
  };
  const pickObAvatar=(e)=>pickAvatarInto(e,setObAvatar);
  const pickNewAvatar=(e)=>pickAvatarInto(e,setNewAvatar);
  // その子の写真（記録・アルバム）の photo id 一覧（新しい順・重複なし）。名刺写真ピッカー用。
  const memberPhotoIds=(mid)=>{const seen=new Set();const out=[];[...items].filter(x=>x.space===mid).sort((a,b)=>String(b.date||"").localeCompare(String(a.date||""))).forEach(x=>photoIdsOf(x).forEach(p=>{if(!seen.has(p)){seen.add(p);out.push(p);}}));return out;};
  // 名刺専用写真：新しい写真をアップロード（専用コピーとして IDB に保存し、cardPhoto には photo id を持たせる）。
  const pickPetCardPhoto=async(e)=>{
    const file=e.target.files&&e.target.files[0];e.target.value="";if(!file)return;
    if(file.size>20*1024*1024){showFlash(t("toast.fileTooBig"));return;}
    try{const dataUrl=await downscaleImage(file,760,0.8);const pid="cp"+Date.now();const ok=await photoStorage.set(`photo:${pid}`,dataUrl);if(!ok){showFlash(t("toast.storageFull"));return;}setPhotos(p=>({...p,[pid]:dataUrl}));setEditCardPhoto(pid);setCardPickOpen(false);}
    catch(er){showFlash(t("toast.imgFail"));}
  };
  // 名刺専用写真：この子の既存の写真から選ぶ。元の写真は記録と共有の実体なので、名刺用に専用コピーを作ってから使う
  // （元の記録を消しても名刺の写真が壊れないように）。
  const pickCardPhotoFromAlbum=async(pid)=>{
    try{
      let src=photos[pid];if(!src)src=await photoStorage.get(`photo:${pid}`);
      if(!src){showFlash(t("toast.imgFail"));return;}
      const npid="cp"+Date.now();const ok=await photoStorage.set(`photo:${npid}`,src);if(!ok){showFlash(t("toast.storageFull"));return;}
      setPhotos(p=>({...p,[npid]:src}));setEditCardPhoto(npid);setCardPickOpen(false);
    }catch(e){showFlash(t("toast.imgFail"));}
  };
  // 名刺の追加写真：新しい写真をアップロード（専用コピー。最大3枚まで）。
  const pickCardExtraPhoto=async(e)=>{
    const file=e.target.files&&e.target.files[0];e.target.value="";if(!file)return;
    if(editCardPhotos.length>=3)return;
    if(file.size>20*1024*1024){showFlash(t("toast.fileTooBig"));return;}
    try{const dataUrl=await downscaleImage(file,760,0.8);const pid="cp"+Date.now();const ok=await photoStorage.set(`photo:${pid}`,dataUrl);if(!ok){showFlash(t("toast.storageFull"));return;}setPhotos(p=>({...p,[pid]:dataUrl}));setEditCardPhotos(list=>list.length>=3?list:[...list,pid]);setCardExtraPickOpen(false);}
    catch(er){showFlash(t("toast.imgFail"));}
  };
  // 名刺の追加写真：この子の既存の写真から選ぶ（メイン写真と同じく専用コピーを作る）。
  const pickCardExtraFromAlbum=async(pid)=>{
    if(editCardPhotos.length>=3)return;
    try{
      let src=photos[pid];if(!src)src=await photoStorage.get(`photo:${pid}`);
      if(!src){showFlash(t("toast.imgFail"));return;}
      const npid="cp"+Date.now();const ok=await photoStorage.set(`photo:${npid}`,src);if(!ok){showFlash(t("toast.storageFull"));return;}
      setPhotos(p=>({...p,[npid]:src}));setEditCardPhotos(list=>list.length>=3?list:[...list,npid]);setCardExtraPickOpen(false);
    }catch(e){showFlash(t("toast.imgFail"));}
  };
  // 名刺写真ピッカーを開いたら、その子の写真サムネイルを先読みする（photos に無い分だけ IDB から）。
  useEffect(()=>{
    if((!cardPickOpen&&!cardExtraPickOpen)||!cardScreenId)return;
    let alive=true;
    (async()=>{for(const pid of memberPhotoIds(cardScreenId)){if(!photos[pid]){try{const s=await photoStorage.get(`photo:${pid}`);if(s&&alive)setPhotos(p=>p[pid]?p:({...p,[pid]:s}));}catch(e){}}}})();
    return()=>{alive=false;};
    // eslint-disable-next-line react-hooks/exhaustive-deps
  },[cardPickOpen,cardExtraPickOpen,cardScreenId]);
  // メンバーのアイコン表示（写真があれば写真、無ければ絵文字）
  const avatarNode=(m,cls)=>{const src=m&&m.avatar&&photos[m.avatar];return src?<img className={"yl-avatar "+(cls||"")} src={src} alt=""/>:<span className={cls}>{m?memberEmojiOf(m):""}</span>;};

  // --- Quick-add functions ---
  const openQuickAdd=(kind,emoji,title,space,lastDate,repeat,repeatDays)=>{
    setQuickAdd({kind,emoji,title,space,lastDate:lastDate||null,repeat:repeat||"none",repeatDays:repeatDays||[]});
    setQuickDate("");setQuickTime("");setQuickPlace("");
  };
  const openQuickCopy=(it)=>{
    setQuickAdd({kind:it.careKind,emoji:it.emoji,title:it.title,space:it.space,lastDate:it.dueDate||null,repeat:it.repeat||"none",repeatDays:repeatDaysOf(it)||[]});
    setQuickDate("");setQuickTime(it.time||"");setQuickPlace(it.place||"");
  };
  const saveQuickAdd=()=>{
    if(!quickAdd)return;
    const base={id:"x"+Date.now(),space:quickAdd.space,title:quickAdd.title,emoji:quickAdd.emoji,type:"care",careKind:quickAdd.kind,done:false,createdAt:Date.now(),dueDate:quickDate||undefined,time:quickTime||undefined,place:quickPlace.trim()||undefined,repeat:quickAdd.repeat,repeatDays:quickAdd.repeatDays};
    const next=[...items,base];
    persist(members,next);
    saveItemToFs(base).catch(()=>{});
    setQuickAdd(null);setQuickDate("");setQuickTime("");setQuickPlace("");
    showFlash(t("toast.addedBang"));
  };

  // --- ルーティン（1日のタスク）---
  const todayIso=iso(new Date());
  const openRoutineTemplate=(t)=>setRoutineEdit({title:t.title,emoji:t.emoji,time:t.time,reminders:[0],space:tab,repeat:"daily",repeatDays:null});
  const openRoutineCustom=()=>setRoutineEdit({title:"",emoji:curKind==="pet"?"🐾":"⏰",time:"08:00",reminders:[0],space:tab,repeat:"daily",repeatDays:null});
  const openRoutineEdit=(r)=>setRoutineEdit({id:r.id,title:r.title,emoji:r.emoji||"⏰",time:r.time||"08:00",reminders:r.reminders||[],space:r.space,repeat:r.repeat||"daily",repeatDays:Array.isArray(r.repeatDays)?r.repeatDays:null});
  const toggleRoutineReminder=(mins)=>setRoutineEdit(prev=>prev?{...prev,reminders:prev.reminders.includes(mins)?prev.reminders.filter(m=>m!==mins):[...prev.reminders,mins].sort((a,b)=>a-b)}:prev);
  const saveRoutine=()=>{
    if(!routineEdit)return;
    const title=routineEdit.title.trim();if(!title){showFlash(t("toast.titleNeeded"));return;}
    const rem=routineEdit.reminders.length?routineEdit.reminders:undefined;
    // 頻度：毎日（daily）／曜日指定（weekly＋repeatDays）。予定フォームと同じ保存形式。
    const rep=routineEdit.repeat==="weekly"?"weekly":"daily";
    const repDays=rep==="weekly"&&Array.isArray(routineEdit.repeatDays)&&routineEdit.repeatDays.length?[...routineEdit.repeatDays].sort((a,b)=>a-b):undefined;
    let next,savedId;
    if(routineEdit.id){
      savedId=routineEdit.id;
      next=items.map(x=>x.id===routineEdit.id?{...x,title,emoji:routineEdit.emoji,time:routineEdit.time,reminders:rem,repeat:rep,repeatDays:repDays}:x);
    }else{
      savedId="rt"+Date.now();
      next=[...items,{id:savedId,space:routineEdit.space,type:"routine",title,emoji:routineEdit.emoji,time:routineEdit.time,reminders:rem,repeat:rep,...(repDays?{repeatDays:repDays}:{}),doneDate:null,createdAt:Date.now()}];
    }
    persist(members,next);
    if(!routineEdit.id)track("task_add",{task_type:"routine"});
    const saved=next.find(x=>x.id===savedId);
    if(saved)saveItemToFs(saved).catch(()=>{});
    setRoutineEdit(null);showFlash(t("toast.routineSaved"));
  };
  const toggleRoutine=(id)=>{
    const r=items.find(x=>x.id===id);if(!r)return;
    const done=r.doneDate===todayIso;
    if(!done)track("task_complete",{task_type:"routine"});
    const prevDone=r.doneDate;
    const next=items.map(x=>x.id===id?{...x,doneDate:done?null:todayIso}:x);
    persist(members,next);
    const u=next.find(x=>x.id===id);if(u)saveItemToFs(u).catch(()=>{});
    if(!done)beginActionUndo((r.emoji||"⏰")+" "+r.title+" "+t("status.done"),()=>{const cur=itemsRef.current;const nx=cur.map(x=>x.id===id?{...x,doneDate:prevDone}:x);persist(membersRef.current,nx);const uu=nx.find(x=>x.id===id);if(uu)saveItemToFs(uu).catch(()=>{});});
  };
  const removeRoutine=(id)=>{
    const r=items.find(x=>x.id===id);
    deleteItemFromFs(r).catch(()=>{});
    persist(members,items.filter(x=>x.id!==id));
    setRoutineEdit(null);
  };
  const routines=useMemo(()=>items.filter(x=>x.space===tab&&x.type==="routine").sort((a,b)=>(a.time||"99:99").localeCompare(b.time||"99:99")),[items,tab]);
  // 今日が実施日のルーティンだけが「今日のルーティン」（曜日指定対応・追加項目）。
  const routinesToday=useMemo(()=>routines.filter(r=>routineDueOn(r,todayIso)),[routines,todayIso]);
  const routineDone=routinesToday.filter(r=>r.doneDate===todayIso).length;

  // --- 消耗品ストック（買った日＋サイクルで残量を自動計算）---
  const openSupplyTemplate=(t)=>setSupplyEdit({title:t.title,emoji:t.emoji,cycleDays:t.cycleDays,lastBought:todayIso,space:tab});
  // ストックの初期絵文字は種別のセット先頭（人のメンバーでペット寄りの🥫が初期値にならないように）。
