      const calc=(k)=>{const all=recs.filter(x=>x.tkind===k);const r=all.filter(x=>x.success!=null);const s=r.filter(x=>x.success).length;const br=all.filter(x=>x.bristol).map(x=>x.bristol);const avg=br.length?Math.round(br.reduce((a,b)=>a+b,0)/br.length*10)/10:null;return{total:r.length,success:s,rate:r.length?Math.round(s/r.length*100):null,avgBristol:avg,brCount:br.length};};
