                                      {r.exAct&&exerciseMeta(r.exAct)&&<span className="yl-dayrec-chip"><Icon name="activity" size={13}/> {exerciseLabelOf(r)}{r.exMin?` ${r.exMin}${t("diary.minSuffix")}`:""}</span>}
