              {(tab==="me"||(activeMember&&activeMember.kind==="person"))&&<label className="yl-opt">{t("chart.height")}<span className="yl-health-field"><input type="number" inputMode="decimal" step="0.1" className="yl-health-num" value={healthH} onChange={e=>setHealthH(e.target.value)} placeholder="0.0"/><span className="yl-health-unit">cm</span></span></label>}
              {(activeMember&&activeMember.personType==="baby")&&<label className="yl-opt">{t("health.headCirc")}<span className="yl-health-field"><input type="number" inputMode="decimal" step="0.1" className="yl-health-num" value={healthHead} onChange={e=>setHealthHead(e.target.value)} placeholder="0.0"/><span className="yl-health-unit">cm</span></span></label>}
