        const todayDiary=diaryRecords.filter(r=>r.date===todayIso);
        const diarySum=(r)=>[r.energy&&energyMetaOf(r.energy)&&lblOf(energyMetaOf(r.energy)),r.appetite&&appetiteMetaOf(r.appetite)&&`${t("sheet.appetiteColon")}${lblOf(appetiteMetaOf(r.appetite))}`,r.poop&&diaryMeta(DIARY_POOP,r.poop)&&`${t("sheet.poopColon")}${lblOf(diaryMeta(DIARY_POOP,r.poop))}`,r.sleep&&t("sheet.sleepH",{n:r.sleep}),(r.symptoms||[]).map(sk=>symptomMeta(sk)&&lblOf(symptomMeta(sk))).filter(Boolean).join("・"),r.note].filter(Boolean).join(" / ");
        const notes=familyNotes.slice(0,5);
