                {isPet&&docD.walkSlots.hours.length>0&&<div className="yl-vetsum-sec"><h3>🐾 {t("sheet.walkTime")}</h3><ul>{docD.walkSlots.hours.map((h,i)=><li key={i}>{t("sheet.walkHour",{h})}</li>)}</ul></div>}
