                {!isPet&&<div className="yl-vetsum-sec"><h3>{t("sheet.todayChores")}</h3>{todayChores.length?<ul>{todayChores.map(c=><li key={c.id}>{c.emoji||"✓"} {c.title}</li>)}</ul>:<p className="yl-vetsum-none">{t("sheet.noRecordsYet")}</p>}</div>}
